struct state_list {
    int *states;
    int num_states;
    struct state_list *next;
};

struct state_list *create_state_list(int *states, int num_states, struct fsa *fsa, int last_state) {
    struct state_list *new_list = malloc(sizeof(struct state_list)));
    if (!new_list) {
        return NULL;
    }
    new_list->states = malloc(num_states * sizeof(int)));
    if (!new_list->states) {
        free(new_list);
        return NULL;
    }
    for (int i = 0; i < num_states; i++) {
        new_list->states[i] = states[i];
    }
    new_list->num_states = num_states;
    new_list->next = NULL;
    if (last_state >= 0) {
        struct state_list *current = fsa->state_lists;
        while (current && current->num_states > 0) {
            if (current->states[0] == last_state) {
                current->next = new_list;
                break;
            }
            current = current->next;
        }
    }
    return new_list;
}

