typedef struct {
    char *key;
    char *value;
} ResourceItem;

typedef struct {
    ResourceItem *items;
    size_t count;
} ResourceBundle;

int load_resource_bundle(const char *path, ResourceBundle *bundle) {
    FILE *file = fopen(path, "r");
    if (!file) {
        perror("fopen");
        return -1;
    }

    size_t count = 0;
    char line[256];
    while (fgets(line, sizeof(line)), file)) {
        char *key = strtok(line, "=");
        char *value = strtok(NULL, "=");
        if (key && value) {
            ResourceItem *item = realloc(bundle->items, (count + 1) * sizeof(ResourceItem)));
            if (!item) {
                perror("realloc");
                fclose(file);
                return -1;
            }
            bundle->items = item;
            bundle->items[count].key = strdup(key);
            bundle->items[count].value = strdup(value);
            count++;
        }
    }

    fclose(file);
    bundle->count = count;
    return 0;
}

