int process_text_file(const char *filename, char ***strings, int **counts) {
    FILE *file = fopen(filename, "r");
    if (!file) return -1;

    char line[1024];
    int total = 0;

    while (fgets(line, sizeof(line), file))) {
        char *trimmed = strtok(line, "\n");
        if (!trimmed || trimmed[0] == '#' || trimmed[0] == '\0') continue;

        char *token = strtok(trimmed, " \t\n"));
        while (token) {
            if (token[0] == '\'') {
                int len = strlen(token) - 2;
                char *str = malloc(len + 1);
                if (str) {
                    strncpy(str, token + 1, len);
                    str[len] = '\0';
                    strings[0][total] = str;
                    total++;
                }
            } else if (token[0] == '!')) {
                int count = atoi(token + 1);
                counts[0][total] = count;
                total++;
            }
            token = strtok(NULL, " \t\n"));
        }
    }

    fclose(file);
    return total;
}

