int compress_tiff(TIFF *tif, const char *output_file) {
    uint32_t width, height;
    TIFFGetField(tif, TIFFTAG_IMAGEWIDTH, &width);
    TIFFGetField(tif, TIFFTAG_IMAGELENGTH, &height);

    uint8_t *buffer = (uint8_t *)malloc(width * height * sizeof(uint8_t)));
    if (!buffer) {
        return -1;
    }

    TIFFReadRGBAImage(tif, width, height, (uint32_t *)buffer), 0);

    TIFF *out = TIFFOpen(output_file, "w");
    if (!out) {
        free(buffer);
        return -1;
    }

    TIFFSetField(out, TIFFTAG_IMAGEWIDTH, width);
    TIFFSetField(out, TIFFTAG_IMAGELENGTH, height);
    TIFFSetField(out, TIFFTAG_SAMPLESPERPIXEL, 4);
    TIFFSetField(out, TIFFTAG_BITSPERSAMPLE, 8);
    TIFFSetField(out, TIFFTAG_COMPRESSION, COMPRESSION_JPEG);
    TIFFSetField(out, TIFFTAG_PHOTOMETRIC, PHOTOMETRIC_RGB);

    for (uint32_t y = 0; y < height; y++) {
        uint8_t *row = buffer + y * width * 4;
        for (uint32_t x = 0; x < width; x++) {
            uint8_t *pixel = row + x * 4;
            uint8_t temp = pixel[0];
            pixel[0] = pixel[2];
            pixel[2] = temp;
        }
        TIFFWriteScanline(out, (uint32_t *)row), y);
    }

    TIFFClose(out);
    free(buffer);
    return 0;
}

