struct scheduler {
    pthread_t *threads;
    int *cpu_affinity;
    int num_threads;
    int suspend_threshold;
    pthread_mutex_t mutex;
};

struct scheduler *init_scheduler(int num_threads, int suspend_threshold, int (*assign_cpu)(int)) {
    struct scheduler *sched = malloc(sizeof(struct scheduler)));
    if (!sched) return NULL;
    sched->num_threads = num_threads;
    sched->suspend_threshold = suspend_threshold;
    sched->threads = malloc(num_threads * sizeof(pthread_t)));
    sched->cpu_affinity = malloc(num_threads * sizeof(int)));
    if (!sched->threads || !sched->cpu_affinity) {
        free(sched->threads);
        free(sched->cpu_affinity);
        free(sched);
        return NULL;
    }
    for (int i = 0; i < num_threads; i++) {
        sched->cpu_affinity[i] = assign_cpu(i);
    }
    pthread_mutex_init(&sched->mutex, NULL);
    return sched;
}

