} Server;

Server* parse_server_list(const char* server_list, int* count) {
    if (!server_list || !count) return NULL;
    *count = 0;
    Server* servers = NULL;
    const char* token = strtok((char*)server_list, ",");
    while (token) {
        char* hostname = strtok(token, ":");
        char* port_str = strtok(NULL, ":");
        if (hostname && port_str) {
            int port = atoi(port_str);
            servers = realloc(servers, (*count + 1)) * sizeof(Server));
            if (servers) {
                strncpy(servers[*count].hostname, hostname, sizeof(servers[*count].hostname]) - 1);
                servers[*count].hostname[sizeof(servers[*count].hostname]) - 1] = '\0';
                servers[*count].port = port;
                (*count)++;
            }
        }
        token = strtok(NULL, ",");
    }
    return servers;
}

