#define STACK_SIZE 1024

typedef struct {
    char *buffer;
    size_t top;
    size_t size;
} Stack;

void stack_init(Stack *s) {
    s->buffer = malloc(STACK_SIZE);
    s->top = 0;
    s->size = STACK_SIZE;
}

void stack_push(Stack *s, char c) {
    if (s->top >= s->size) {
        s->size *= 2;
        s->buffer = realloc(s->buffer, s->size);
    }
    s->buffer[s->top++] = c;
}

void stack_pop(Stack *s) {
    if (s->top > 0) {
        s->top--;
    }
}

void stack_clear(Stack *s) {
    s->top = 0;
}

void process_input(const char *input) {
    Stack stack;
    stack_init(&stack);

    for (size_t i = 0; i < strlen(input); i++) {
        stack_push(&stack, input[i]);
    }

    stack_push(&stack, '\n');

    char *line = stack.buffer;
    size_t len = stack.top;

    char *function = strtok(line, " ");
    char *args = strtok(NULL, "\n");

    printf("Function: %s\n", function);
    printf("Arguments: %s\n", args);

    stack_clear(&stack);
    free(stack.buffer);
}

