char* replace_substrings(const char* input, const char* old_substring, const char* new_substring) {
    if (!input || !old_substring || !new_substring) {
        return NULL;
    }

    size_t old_len = strlen(old_substring);
    size_t new_len = strlen(new_substring);
    size_t input_len = strlen(input);
    size_t count = 0;
    size_t pos = 0;
    char* result = NULL;

    // Count occurrences of old_substring
    while ((pos = strstr(input + pos, old_substring))) != NULL) {
        count++;
        pos += old_len;
    }

    // Allocate memory for the result string
    result = (char*)malloc(input_len + count * (new_len - old_len)) + 1);
    if (!result) {
        return NULL;
    }

    // Replace occurrences of old_substring with new_substring
    pos = 0;
    while ((pos = strstr(input + pos, old_substring))) != NULL) {
        strncpy(result + strlen(result), input + pos, old_len);
        strncpy(result + strlen(result), new_substring, new_len);
        pos += old_len;
    }

    // Append remaining characters from input string
    strncpy(result + strlen(result), input + pos, input_len - pos);

    return result;
}

