int count_lines(const char *filename) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("fopen");
        return -1;
    }

    int line_count = 0;
    char ch;
    while ((ch = fgetc(file)) != EOF) {
        if (ch == '\n') {
            line_count++;
        }
    }

    if (ferror(file)) {
        perror("fgetc");
        fclose(file);
        return -1;
    }

    fclose(file);
    return line_count;
}

