        fprintf(stderr, "Failed to finalize encryption\n");
        EVP_CIPHER_CTX_free(ctx);
        free(ciphertext);
        return NULL;
    }
    ciphertext_len += len;
    ciphertext[ciphertext_len] = '\0';
    *ciphertext_len = ciphertext_len;
    EVP_CIPHER_CTX_free(ctx);
    return ciphertext;
}

