    size_t len = 0;

    FD_ZERO(&read_fds);
    FD_SET(STDIN_FILENO, &read_fds);

    timeout.tv_sec = 5;
    timeout.tv_usec = 0;

    int ret = select(STDIN_FILENO + 1, &read_fds, NULL, NULL, &timeout);
    if (ret == -1) {
        perror("select");
        return NULL;
    } else if (ret == 0) {
        fprintf(stderr, "Timeout\n");
        return NULL;
    }

    if (FD_ISSET(STDIN_FILENO, &read_fds))) {
        ssize_t n = getline(&line, &len, stdin);
        if (n == -1) {
            perror("getline");
            free(line);
            return NULL;
        }
    }

    return line;
}

