#define BUFFER_SIZE 1024

typedef struct {
    char buffer[BUFFER_SIZE];
    size_t start;
    size_t end;
    FILE *fp;
} LineBuffer;

LineBuffer *lb_init(FILE *fp) {
    LineBuffer *lb = malloc(sizeof(LineBuffer)));
    if (!lb) return NULL;
    lb->fp = fp;
    lb->start = lb->end = 0;
    return lb;
}

void lb_destroy(LineBuffer *lb) {
    if (lb) {
        fclose(lb->fp);
        free(lb);
    }
}

int lb_push_back(LineBuffer *lb, const char *line) {
    if (lb->end + strlen(line) + 2 > BUFFER_SIZE) return -1;
    strcpy(lb->buffer + lb->end), line);
    lb->end += strlen(line) + 1;
    return 0;
}

int lb_get_next_line(LineBuffer *lb, char *line, size_t max_len) {
    if (lb->start == lb->end) {
        if (fgets(lb->buffer, BUFFER_SIZE, lb->fp)) == NULL) {
            return -1;
        }
        lb->end = strlen(lb->buffer));
    }
    size_t len = strcspn(lb->buffer + lb->start), "\n");
    if (len + 1 > max_len) return -1;
    strncpy(line, lb->buffer + lb->start, len);
    line[len] = '\0';
    lb->start += len + 1;
    return 0;
}

