unsigned char *generate_dns_response(unsigned char *buffer, int num_services) {
    for (int i = 0; i < num_services; i++) {
        char service_name[64];
        snprintf(service_name, sizeof(service_name), "service%d.example.com", i);

        memcpy(buffer, service_name, strlen(service_name));
        buffer += strlen(service_name);

        uint16_t record_type = 0x0005; // PTR record
        uint16_t record_class = 0x0001; // IN class
        uint32_t ttl = 4 * 60; // 4 minutes
        uint16_t rd_length = strlen(service_name);

        memcpy(buffer, &record_type, 2);
        memcpy(buffer + 2, &record_class, 2);
        memcpy(buffer + 4, &ttl, 4);
        memcpy(buffer + 8, &rd_length, 2);
        buffer += 10;

        memcpy(buffer, service_name, strlen(service_name)));
        buffer += strlen(service_name);
    }

    return buffer;
}

