int execute_prepared_stmt(MYSQL *conn, const char *stmt_str, ...) {
    MYSQL_STMT *stmt = mysql_stmt_init(conn);
    if (!stmt) return -1;

    if (mysql_stmt_prepare(stmt, stmt_str, strlen(stmt_str)))) {
        mysql_stmt_close(stmt);
        return -1;
    }

    va_list args;
    va_start(args, stmt_str);

    int param_count = mysql_stmt_param_count(stmt);
    MYSQL_BIND bind[param_count];
    memset(bind, 0, sizeof(bind)));

    for (int i = 0; i < param_count; i++) {
        bind[i].buffer_type = MYSQL_TYPE_STRING;
        bind[i].buffer = va_arg(args, char *));
        bind[i].length = va_arg(args, unsigned long *));
        bind[i].is_null = va_arg(args, my_bool *));
    }

    if (mysql_stmt_bind_param(stmt, bind))) {
        mysql_stmt_close(stmt);
        return -1;
    }

    if (mysql_stmt_execute(stmt))) {
        mysql_stmt_close(stmt);
        return -1;
    }

    MYSQL_RES *result = mysql_stmt_result_metadata(stmt);
    if (!result) {
        mysql_stmt_close(stmt);
        return -1;
    }

    MYSQL_ROW row;
    while ((row = mysql_fetch_row(result)))) {
        for (int i = 0; i < mysql_num_fields(result); i++) {
            printf("%s ", row[i]);
        }
        printf("\n");
    }

    mysql_free_result(result);
    mysql_stmt_close(stmt);
    return 0;
}

