static PyObject* axis_elements(PyObject *self, PyObject *args) {
    PyObject *py_array;
    int axis;
    if (!PyArg_ParseTuple(args, "Oi", &py_array, &axis))) {
        return NULL;
    }
    if (!PyArray_Check(py_array))) {
        PyErr_SetString(PyExc_TypeError, "Input must be a NumPy array"));
        return NULL;
    }
    npy_intp ndim = PyArray_NDIM(py_array);
    if (axis < 0 || axis >= ndim) {
        PyErr_SetString(PyExc_ValueError, "Axis out of bounds"));
        return NULL;
    }
    npy_intp *shape = PyArray_SHAPE(py_array);
    npy_intp *strides = PyArray_STRIDES(py_array);
    npy_intp new_shape[ndim];
    npy_intp new_strides[ndim];
    for (npy_intp i = 0; i < ndim; i++) {
        new_shape[i] = shape[i];
        new_strides[i] = strides[i];
    }
    new_shape[axis] = 1;
    new_strides[axis] = 0;
    PyObject *result = PyArray_SimpleNew(ndim, new_shape, PyArray_TYPE(py_array)));
