struct path_table {
    char *names;
    int count;
};

int traverse_directory(const char *root, const char *path, struct path_table *pt) {
    DIR *dir;
    struct dirent *entry;
    char full_path[1024];
    int found = 0;

    snprintf(full_path, sizeof(full_path)), "%s/%s", root, path);

    dir = opendir(full_path);
    if (!dir) {
        perror("opendir");
        return -1;
    }

    while ((entry = readdir(dir))) != NULL) {
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0) {
            continue;
        }
        if (strcmp(entry->d_name, path)) == 0) {
            found = 1;
            break;
        }
    }

    closedir(dir);

    if (found) {
        pt->names = realloc(pt->names, (pt->count + 1) * sizeof(char *)));
        pt->names[pt->count] = strdup(path);
        pt->count++;
    }

    return found;
}

