        printf("Wi-Fi module is currently ON.\n");
        printf("Enter 0 to turn OFF the Wi-Fi module: ");
    } else {
        printf("Wi-Fi module is currently OFF.\n");
        printf("Enter 1 to turn ON the Wi-Fi module: ");
    }

