        fp = fopen(module->device_path, "w");
        if (fp != NULL) {
            fprintf(fp, "%d\n", new_state);
            fclose(fp);
            module->current_state = new_state;
            printf("Wi-Fi module power state changed to %d.\n", new_state);
        } else {
            printf("Failed to open device file for writing.\n");
        }
    } else {
        printf("Invalid input. Please enter 0 or 1.\n");
    }
}

