    char key[100];
    char value[1000];
} KeyValuePair;

KeyValuePair* read_key_value_pairs(const char* filename, int* count) {
    FILE* file = fopen(filename, "r");
    if (!file) {
        perror("fopen");
        return NULL;
    }

    KeyValuePair* pairs = NULL;
    int size = 0;
    int i = 0;

    while (fscanf(file, "%99[^=]=%999[^\n]", pairs[i].key, pairs[i].value) == 2) {
        i++;
        if (i >= size) {
            size += 10;
            pairs = realloc(pairs, size * sizeof(KeyValuePair)));
        }
    }

    fclose(file);
    *count = i;
    return pairs;
}

