#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <arpa/inet.h>

#define BUFFER_SIZE 1024

int retrieve_file(const char *filename, const char *ip_address, int port) {
    int sockfd;
    struct sockaddr_in server_addr;
    char request_packet[BUFFER_SIZE];
    char response_packet[BUFFER_SIZE];
    FILE *fp;
    ssize_t bytes_read;

    // Create socket
    if ((sockfd = socket(AF_INET, SOCK_STREAM, 0))) < 0) {
        perror("Socket creation failed");
        return -1;
    }

    // Set server address
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(port);
    if (inet_pton(AF_INET, ip_address, &server_addr.sin_addr)) <= 0) {
        perror("Invalid address/ Address not supported");
        return -1;
    }

    // Connect to server
    if (connect(sockfd, (struct sockaddr *)&server_addr), sizeof(server_addr))) < 0) {
        perror("Connection Failed");
        return -1;
    }

    // Build request packet
    snprintf(request_packet, BUFFER_SIZE, "GET %s", filename);

    // Send request packet
    if (send(sockfd, request_packet, strlen(request_packet)), 0) < 0) {
        perror("Send failed");
        return -1;
    }

    // Receive response packet
    if (recv(sockfd, response_packet, BUFFER_SIZE - 1), 0) < 0) {
        perror("Receive failed");
        return -1;
    }
    response_packet[BUFFER_SIZE - 1] = '\0';

    // Open file for writing
    fp = fopen(filename, "wb");
    if (!fp) {
        perror("File open failed");
        return -1;
    }

    // Write file data to local file
    while ((bytes_read = recv(sockfd, response_packet, BUFFER_SIZE - 1), 0)) > 0) {
        fwrite(response_packet, 1, bytes_read, fp);
    }
    if (bytes_read < 0) {
        perror("Receive failed");
        fclose(fp);
        return -1;
    }

    // Close file and socket
    fclose(fp);
    close(sockfd);

    return 0;
}

