int read_path_table(const char *volume_descriptor, char **path_table_buffer) {
    if (!volume_descriptor || !path_table_buffer) {
        return -1;
    }

    // Assuming the path table starts at offset 2048
    const char *path_table_start = volume_descriptor + 2048;

    // Calculate the size of the path table
    size_t path_table_size = strlen(path_table_start) + 1;

    // Allocate memory for the path table buffer
    *path_table_buffer = (char *)sysmalloc(path_table_size);
    if (!*path_table_buffer) {
        return -1;
    }

    // Copy the path table into the allocated buffer
    memcpy(*path_table_buffer, path_table_start, path_table_size);

    return path_table_size;
}

