    struct json_object *token_type;
    struct json_object *refresh_token;

    parsed_json = json_tokener_parse(json_str);
    if (!parsed_json) {
        return false;
    }

    if (!json_object_object_get_ex(parsed_json, "access_token", &access_token)) {
        json_object_put(parsed_json);
        return false;
    }

    if (!json_object_object_get_ex(parsed_json, "expires_in", &expires_in)) {
        json_object_put(parsed_json);
        return false;
    }

    if (!json_object_object_get_ex(parsed_json, "token_type", &token_type)) {
        json_object_put(parsed_json);
        return false;
    }

    if (json_object_get_type(access_token) != json_type_string ||
        json_object_get_type(expires_in) != json_type_int ||
        json_object_get_type(token_type) != json_type_string) {
        json_object_put(parsed_json);
        return false;
    }

    if (json_object_get_int(expires_in) <= 0)) {
        json_object_put(parsed_json);
        return false;
    }

    if (strcmp(json_object_get_string(token_type)), "Bearer") != 0) {
        json_object_put(parsed_json);
        return false;
    }

    json_object_put(parsed_json);
    return true;
}

