const char *verify_jwt(const char *jwt, const char *secret_key) {
    const char *header = strtok(jwt, ".");
    const char *payload = strtok(NULL, ".");
    const char *signature = strtok(NULL, ".");

    EVP_PKEY *pkey = NULL;
    FILE *fp = fopen(secret_key, "r");
    if (fp) {
        pkey = PEM_read_PrivateKey(fp, NULL, NULL, NULL));
        fclose(fp);
    }

    if (!pkey) {
        return NULL;
    }

    EVP_MD_CTX *ctx = EVP_MD_CTX_new();
    EVP_DigestInit_ex(ctx, EVP_sha256(), NULL);
    EVP_DigestUpdate(ctx, payload, strlen(payload)));
    unsigned char digest[EVP_MAX_MD_SIZE];
    unsigned int digest_len;
    EVP_DigestFinal_ex(ctx, digest, &digest_len));
    EVP_MD_CTX_free(ctx);

    unsigned char *decoded_signature = NULL;
    int decoded_len = base64_decode(signature, strlen(signature), &decoded_signature));
    if (decoded_len <= 0) {
        EVP_PKEY_free(pkey);
        return NULL;
    }

    EVP_PKEY_CTX *pctx = EVP_PKEY_CTX_new(pkey, NULL);
    if (!pctx) {
        EVP_PKEY_free(pkey);
        free(decoded_signature);
        return NULL;
    }

    if (EVP_PKEY_verify_init(pctx) <= 0) {
        EVP_PKEY_CTX_free(pctx);
        EVP_PKEY_free(pkey);
        free(decoded_signature);
        return NULL;
    }

    if (EVP_PKEY_verify(pctx, decoded_signature, decoded_len, (unsigned char *)payload, strlen(payload))) <= 0) {
        EVP_PKEY_CTX_free(pctx);
        EVP_PKEY_free(pkey);
        free(decoded_signature);
        return NULL;
    }

    EVP_PKEY_CTX_free(pctx);
    EVP_PKEY_free(pkey);
    free(decoded_signature);
    return payload;
}

