unsigned char *hash_buffer(const unsigned char *input, size_t input_len, const char *algorithm) {
    unsigned char *output = malloc(algorithm == "MD5" ? MD5_DIGEST_LENGTH : SHA_DIGEST_LENGTH));
    if (!output) return NULL;
    if (strcmp(algorithm, "MD5")) == 0) {
        MD5_CTX md5;
        MD5_Init(&md5);
        MD5_Update(&md5, input, input_len);
        MD5_Final(output, &md5);
    } else if (strcmp(algorithm, "SHA")) == 0) {
        SHA256_CTX sha256;
        SHA256_Init(&sha256);
        SHA256_Update(&sha256, input, input_len);
        SHA256_Final(output, &sha256);
    }
    return output;
}

