using namespace std;

pair<vector<int>, int> findBestCombination(const vector<pair<int, bool>>>& values, int target) {
    int n = values.size();
    vector<vector<int>>> dp(n + 1, vector<int>(target + 1, 0)));
    vector<vector<int>>> selected(n + 1, vector<int>(target + 1, 0)));

    for (int i = 1; i <= n; ++i) {
        for (int j = 0; j <= target; ++j) {
            if (j >= values[i - 1].first) {
                if (dp[i - 1][j - values[i - 1].first]] + values[i - 1].first > dp[i - 1][j]] + values[i - 1].first) {
                    dp[i][j] = dp[i - 1][j - values[i - 1].first]] + values[i - 1].first;
                    selected[i][j] = selected[i - 1][j - values[i - 1].first]] + values[i - 1].first;
                } else {
                    dp[i][j] = dp[i - 1][j]] + values[i - 1].first;
                    selected[i][j] = selected[i - 1][j]] + values[i - 1].first;
                }
            } else {
                dp[i][j] = dp[i - 1][j]];
                selected[i][j] = selected[i - 1][j]];
            }
        }
    }

    vector<int> bestCombination;
    int bestSum = 0;
    for (int i = 0; i <= target; ++i) {
        if (dp[n][i]] > bestSum) {
            bestSum = dp[n][i]];
            bestCombination = selected[n][i]];
        }
    }

    return {bestCombination, bestSum};
