std::vector<int> createRandomSortedVectorSet(int minSize, int maxSize, int minValue, int maxValue) {
    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_int_distribution<> sizeDist(minSize, maxSize);
    std::uniform_int_distribution<> valueDist(minValue, maxValue);

    int size = sizeDist(gen);
    std::vector<int> set;
    for (int i = 0; i < size; ++i) {
        int value = valueDist(gen);
        auto it = std::lower_bound(set.begin(), set.end(), value));
        if (it == set.end() || *it != value) {
            set.insert(it, value);
        }
    }
    return set;
}

