    Page* createPage(int id, const std::string& data) {
        if (pages.find(id) != pages.end()) {
            return nullptr;
        }
        auto page = std::make_unique<Page>(Page{id, data}}));
        pages[id] = std::move(page);
        return pages[id].get();
    }

    Page* getPage(int id) {
        if (pages.find(id) == pages.end()) {
            return nullptr;
        }
        return pages[id].get();
    }

    bool deletePage(int id) {
        if (pages.find(id) == pages.end()) {
            return false;
        }
        pages.erase(id);
        return true;
    }

private:
