typedef struct {
    double x, y;
} Point;

typedef struct {
    Point *points;
    int num_points;
} Path;

Path create_path(Point *points, int num_points) {
    Path path;
    path.points = malloc(num_points * sizeof(Point)));
    memcpy(path.points, points, num_points * sizeof(Point)));
    path.num_points = num_points;
    return path;
}

void free_path(Path *path) {
    free(path->points);
    path->points = NULL;
    path->num_points = 0;
}

char *draw_path(Path *path, const char *fill_type) {
    char *result = malloc(1024 * sizeof(char)));
    if (!result) return NULL;
    result[0] = '\0';
    for (int i = 0; i < path->num_points; i++) {
        if (i == 0) {
            sprintf(result + strlen(result), "M %.2f %.2f ", path->points[i].x, path->points[i].y);
        } else {
            sprintf(result + strlen(result), "L %.2f %.2f ", path->points[i].x, path->points[i].y);
        }
    }
    sprintf(result + strlen(result), "Z");
    return result;
}

int simplify_path(Path *path) {
    int simplified = 0;
    for (int i = 1; i < path->num_points - 1; i++) {
        double dx1 = path->points[i + 1].x - path->points[i].x;
        double dy1 = path->points[i + 1].y - path->points[i].y;
        double dx2 = path->points[i].x - path->points[i - 1].x;
        double dy2 = path->points[i].y - path->points[i - 1].y;
        if (dx1 * dx2 + dy1 * dy2 == 0) {
            simplified = 1;
            path->points[i] = path->points[i + 1];
            i--;
        }
    }
    return simplified;
}

