        throw std::runtime_error("Failed to create temporary file");
    }
    std::ofstream ofs(temp_path, std::ios::binary);
    if (!ofs) {
        throw std::runtime_error("Failed to open temporary file for writing");
    }
    ofs.write(data.c_str(), data.size());
    ofs.close();
    return temp_path;
}

std::string load_from_temp_file(const std::string& temp_path) {
    std::ifstream ifs(temp_path, std::ios::binary);
    if (!ifs) {
        throw std::runtime_error("Failed to open temporary file for reading");
    }
    ifs.seekg(0, std::ios::end));
    std::streamsize size = ifs.tellg();
    ifs.seekg(0, std::ios::beg));
    std::string data(size, '\0');
    ifs.read(&data[0], size));
    ifs.close();
    return data;
}

void delete_temp_file(const std::string& temp_path) {
    if (std::remove(temp_path.c_str())) != 0) {
        throw std::runtime_error("Failed to delete temporary file");
    }
}

