int main() {
    cufftHandle plan;
    cufftComplex *h_in, *h_out;
    cufftComplex *d_in, *d_out;

    // Allocate host memory
    h_in = (cufftComplex *)malloc(WIDTH * HEIGHT * sizeof(cufftComplex)));
    h_out = (cufftComplex *)malloc(WIDTH * HEIGHT * sizeof(cufftComplex))));

    // Allocate device memory
    cudaMalloc((void **)&d_in, WIDTH * HEIGHT * sizeof(cufftComplex)));
    cudaMalloc((void **)&d_out, WIDTH * HEIGHT * sizeof(cufftComplex)));

    // Initialize host memory with random values
    for (int i = 0; i < WIDTH * HEIGHT; i++) {
        h_in[i].x = rand() / (float)RAND_MAX;
        h_in[i].y = rand() / (float)RAND_MAX;
    }

    // Copy data to device memory
    cudaMemcpy(d_in, h_in, WIDTH * HEIGHT * sizeof(cufftComplex)), cudaMemcpyHostToDevice);

    // Create 2D FFT plan
    cufftPlan2d(&plan, HEIGHT, WIDTH, CUFFT_C2C);

    // Execute 2D FFT
    cufftExecC2C(plan, d_in, d_out, CUFFT_FORWARD);

    // Copy results back to host memory
    cudaMemcpy(h_out, d_out, WIDTH * HEIGHT * sizeof(cufftComplex)), cudaMemcpyDeviceToHost);

    // Clean up
    cufftDestroy(plan);
    cudaFree(d_in);
    cudaFree(d_out);
    free(h_in);
    free(h_out);

    return 0;
}

