int splitNonCanonical(const UChar *text, int32_t length, UChar ***segments, int32_t **segmentLengths) {
    UBreakIterator *brk = ubrk_open(UBRK_CHARACTER, "en", NULL, 0, NULL);
    ubrk_setText(brk, text, length);

    int32_t count = 0;
    int32_t start = ubrk_first(brk);
    while (start != UBRK_DONE) {
        int32_t end = ubrk_next(brk);
        if (end == UBRK_DONE) {
            end = length;
        }
        count++;
        start = end;
    }

    *segments = (UChar **)uprv_malloc(count * sizeof(UChar *)));
    *segmentLengths = (int32_t *)uprv_malloc(count * sizeof(int32_t)));

    ubrk_setText(brk, text, length);
    start = ubrk_first(brk);
    int32_t i = 0;
    while (start != UBRK_DONE) {
        int32_t end = ubrk_next(brk);
        if (end == UBRK_DONE) {
            end = length;
        }
        (*segments)[i] = (UChar *)uprv_malloc((end - start) * sizeof(UChar)));
        uprv_memcpy((*segments)[i]), &text[start], (end - start) * sizeof(UChar));
        (*segmentLengths)[i] = end - start;
        i++;
        start = end;
    }

    ubrk_close(brk);
    return count;
}

