        fprintf(stderr, "Error: upnpDiscover failed with code %d\n", ret);
        return NULL;
    }

    for (struct UPnPDevice *dev = devlist; dev != NULL; dev = dev->next) {
        struct UPnPDevice *newDevice = (struct UPnPDevice *)malloc(sizeof(struct UPnPDevice)));
