int parse_text(const char *text) {
    if (!text) return 0;

    int paragraph_count = 0;
    const char *current = text;

    while (*current) {
        if (*current == '\n' && *(current + 1) == '\n') {
            paragraph_count++;
            current += 2;
        } else {
            current++;
        }
    }

    return paragraph_count;
}

