template <typename T, typename U>
void test_conversion(const char* test_name, T value) {
    U result = static_cast<U>(value);
    std::cout << test_name << ": " << value << " -> " << result << std::endl;
}

int main() {
    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_int_distribution<> dis(0, 1000000));

    std::cout << "Testing MyInt to int conversion..." << std::endl;
    test_conversion("MyInt to int", MyInt<int>(dis(gen))));

    std::cout << "Testing MyInt to double conversion..." << std::endl;
    test_conversion("MyInt to double", MyInt<double>(dis(gen))));

    std::cout << "Testing double to MyFloat conversion..." << std::endl;
    test_conversion("double to MyFloat", static_cast<double>(MyFloat<double>(dis(gen))))));

    std::cout << "Testing MyFloat to double conversion..." << std::endl;
    test_conversion("MyFloat to double", static_cast<double>(MyFloat<double>(dis(gen))))));

    return 0;
}

