bool is_process_running(const std::string& pid_file_path, int magic_number) {
    std::ifstream pid_file(pid_file_path);
    if (!pid_file.is_open()) {
        std::cerr << "Failed to open pid file: " << pid_file_path << std::endl;
        return false;
    }

    std::string pid_str;
    std::getline(pid_file, pid_str);
    pid_file.close();

    if (pid_str.empty()) {
        std::cerr << "Pid file is empty: " << pid_file_path << std::endl;
        return false;
    }

    int pid = std::stoi(pid_str);
    if (pid <= 0) {
        std::cerr << "Invalid pid in pid file: " << pid_file_path << std::endl;
        return false;
    }

    if (kill(pid, 0)) {
        std::cerr << "Process with pid " << pid << " is not running." << std::endl;
        return false;
    }

    if (magic_number != 0 && pid != magic_number) {
        std::cerr << "Pid " << pid << " does not match magic number " << magic_number << "." << std::endl;
        return false;
    }

    std::cout << "Process with pid " << pid << " is running." << std::endl;
    return true;
}

