using namespace std;

struct Edge {
    int src, dest;
};

struct Graph {
    int V, E;
    vector<Edge> edges;
};

double calculateModularity(const Graph& graph, const vector<int>& communities) {
    double modularity = 0.0;
    double m = 0.0;

    for (const auto& edge : graph.edges) {
        m += 1.0;
    }

    for (int i = 0; i < graph.V; ++i) {
        for (int j = i + 1; j < graph.V; ++j) {
            int community_i = communities[i];
            int community_j = communities[j];

            if (community_i == community_j) {
                modularity += 1.0;
            }
        }
    }

    modularity /= (2.0 * m));
    return modularity;
}

void performRearrangements(Graph& graph, vector<int>& communities, double epsilon, int maxPasses) {
    double bestModularity = calculateModularity(graph, communities);
    int passes = 0;

    while (passes < maxPasses) {
        bool improved = false;

        for (int i = 0; i < graph.V; ++i) {
            int currentCommunity = communities[i];
            double maxGain = 0.0;
            int bestCommunity = currentCommunity;

            for (int j = 0; j < graph.V; ++j) {
                if (i == j) continue;
                int srcCommunity = communities[i];
                int destCommunity = communities[j];
                double gain = 0.0;

                if (srcCommunity != destCommunity) {
                    gain = 1.0 - (2.0 * graph.edges.size()) / (4.0 * graph.edges.size()));
                }

                if (gain > maxGain) {
                    maxGain = gain;
                    bestCommunity = destCommunity;
                }
            }

            if (maxGain > epsilon) {
                communities[i] = bestCommunity;
                improved = true;
            }
        }

        if (!improved) break;

        double currentModularity = calculateModularity(graph, communities);

        if (currentModularity > bestModularity) {
            bestModularity = currentModularity;
        }

        passes++;
    }
}

