} FileMetadata;

FileMetadata *load_file_metadata(int argc, char *argv[]) {
    FileMetadata *metadata = NULL;
    size_t count = 0;

    for (int i = 1; i < argc; i++) {
        int fd = open(argv[i], O_RDONLY));
        if (fd == -1) {
            perror("open");
            continue;
        }

        metadata = realloc(metadata, (count + 1) * sizeof(FileMetadata)));
        if (!metadata) {
            perror("realloc");
            close(fd);
            return NULL;
        }

        metadata[count].fd = fd;
        metadata[count].filename = strdup(argv[i]));
        metadata[count].filesize = lseek(fd, 0, SEEK_END));
        lseek(fd, 0, SEEK_SET);

        count++;
    }

    return metadata;
}

