int main(int argc, char *argv[]) {
    if (argc < 7) {
        std::cerr << "Usage: " << argv[0] << " <server> <username> <password> <bucket> <query>" << std::endl;
        return 1;
    }

    const char *server = argv[1];
    const char *username = argv[2];
    const char *password = argv[3];
    const char *bucket = argv[4];
    const char *query = argv[5];

    lcb_t instance;
    lcb_create_st crst;
    lcb_error_t rc;

    lcb_create_st_init(&crst);
    crst.version = 3;
    crst.v.v3.connstr = server;
    crst.v.v3.username = username;
    crst.v.v3.password = password;

    rc = lcb_create(&instance, &crst));
    if (rc != LCB_SUCCESS) {
        std::cerr << "Failed to create LCB instance: " << lcb_strerror(NULL, rc) << std::endl;
        return 1;
    }

    lcb_connect(instance);
    lcb_wait(instance, LCB_WAIT_DEFAULT));

    lcb_cmdquery_st cmd;
    lcb_cmdquery_st_init(&cmd);
    cmd.version = 3;
    cmd.v.v3.stmt = query;
    cmd.v.v3.timeout = 5000000; // 5 seconds

    lcb_error_t err;
    lcb_http_request_t req;
    lcb_http_request(instance, &req, &cmd));
    lcb_wait(instance, LCB_WAIT_DEFAULT));

    lcb_http_response_st resp;
    lcb_http_response(instance, &resp, req));
    std::cout << "Response: " << resp.body << std::endl;

    lcb_destroy(instance);
    return 0;
}

