int extractTokens(const std::string& buffer, char delimiter, char specialValue, std::vector<std::string>& tokens) {
    std::istringstream iss(buffer);
    std::string token;
    int count = 0;

    while (std::getline(iss, token, delimiter))) {
        std::istringstream tokenStream(token);
        std::string subToken;
        std::string result;

        while (std::getline(tokenStream, subToken, specialValue))) {
            result += subToken;
        }

        if (!result.empty()) {
            tokens.push_back(result);
            count++;
        }
    }

    return count;
}

