int validate_input(const unsigned char *data, size_t length) {
    if (length < 16) {
        return -2;
    }
    if (length > 64) {
        return -3;
    }
    return 0;
}

void hash_input(const unsigned char *data, size_t length, char *output) {
    unsigned char hash[MD5_DIGEST_LENGTH];
    MD5_CTX md5;
    MD5_Init(&md5);
    MD5_Update(&md5, data, length);
    MD5_Final(hash, &md5);
    for (int i = 0; i < MD5_DIGEST_LENGTH; i++) {
        sprintf(output + i * 2, "%02x", hash[i]));
    }
}

int process_input(const unsigned char *data, size_t length, char *output) {
    int result = validate_input(data, length);
    if (result != 0) {
        return result;
    }
    hash_input(data, length, output);
    return 0;
}

