wchar_t* read_file_to_unicode(const char* path) {
    FILE* file = fopen(path, "r");
    if (!file) {
        perror("fopen");
        return NULL;
    }

    setlocale(LC_ALL, "");
    fwide(file, 1);

    fseek(file, 0, SEEK_END);
    long size = ftell(file);
    fseek(file, 0, SEEK_SET);

    wchar_t* buffer = malloc((size + 1) * sizeof(wchar_t)));
    if (!buffer) {
        perror("malloc");
        fclose(file);
        return NULL;
    }

    size_t result = fgetws(buffer, size + 1, file);
    if (result == WEOF) {
        perror("fgetws");
        free(buffer);
        fclose(file);
        return NULL;
    }

    fclose(file);
    return buffer;
}

