const int POOL_SIZE = 2;
const int POOL_STRIDE = 2;

std::vector<std::vector<float>>> convolve(
    const std::vector<std::vector<float>>>& input,
    const std::vector<std::vector<float>>>& filter,
    const std::vector<float>& bias,
    int stride = 1) {

    int input_height = input.size();
    int input_width = input[0].size();
    int filter_height = filter.size();
    int filter_width = filter[0].size();

    int output_height = (input_height - filter_height) / stride + 1;
    int output_width = (input_width - filter_width) / stride + 1;

    std::vector<std::vector<float>>> output(output_height, std::vector<float>(output_width)));

    for (int i = 0; i < output_height; ++i) {
        for (int j = 0; j < output_width; ++j) {
            float sum = 0.0f;
            for (int k = 0; k < filter_height; ++k) {
                for (int l = 0; l < filter_width; ++l) {
                    int input_i = i * stride + k;
                    int input_j = j * stride + l;
                    if (input_i >= 0 && input_i < input_height && input_j >= 0 && input_j < input_width) {
                        sum += input[input_i][input_j]] * filter[k][l];
                    }
                }
            }
            output[i][j] = sum + bias[i * stride + j * stride]];
        }
    }

    return output;
}

