#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

#define MAX_TOKENS 100
#define MAX_TOKEN_LENGTH 256

char** parse_multiline_string(const char* input, int* num_tokens) {
    if (!input || !num_tokens) {
        return NULL;
    }

    char** tokens = (char**)malloc(MAX_TOKENS * sizeof(char*)));
    if (!tokens) {
        return NULL;
    }

    const char* line = input;
    int token_count = 0;

    while (line && *line) {
        // Skip leading whitespace
        while (isspace((unsigned char)*line))) {
            line++;
        }

        if (!*line) {
            break;
        }

        // Allocate memory for the token
        char* token = (char*)malloc(MAX_TOKEN_LENGTH * sizeof(char)));
        if (!token) {
            for (int i = 0; i < token_count; i++) {
                free(tokens[i]);
            }
            free(tokens);
            return NULL;
        }

        // Copy the token from the input string
        int token_index = 0;
        while (*line && !isspace((unsigned char)*line))) {
            if (token_index < MAX_TOKEN_LENGTH - 1) {
                token[token_index++] = *line;
            }
            line++;
        }
        token[token_index] = '\0';

        // Add the token to the list
        tokens[token_count++] = token;
    }

    *num_tokens = token_count;
    return tokens;
}

