typedef struct {
    char *data;
    size_t top;
    size_t capacity;
} Stack;

Stack *create_stack(size_t capacity) {
    Stack *s = malloc(sizeof(Stack));
    s->data = malloc(capacity * sizeof(char)));
    s->top = 0;
    s->capacity = capacity;
    return s;
}

void push(Stack *s, char c) {
    if (s->top < s->capacity) {
        s->data[s->top++] = c;
    }
}

char pop(Stack *s) {
    if (s->top > 0) {
        return s->data[--s->top]];
    }
    return '\0';
}

int is_empty(Stack *s) {
    return s->top == 0;
}

void destroy_stack(Stack *s) {
    free(s->data);
    free(s);
}

int case_insensitive_match(const char *str1, const char *str2) {
    Stack *s1 = create_stack(strlen(str1)));
    Stack *s2 = create_stack(strlen(str2)));

    for (int i = 0; str1[i] != '\0'; i++) {
        push(s1, tolower(str1[i])));
    }

    for (int i = 0; str2[i] != '\0'; i++) {
        push(s2, tolower(str2[i])));
    }

    int match = 1;
    while (!is_empty(s1)) && (!is_empty(s2)))) {
        char c1 = pop(s1);
        char c2 = pop(s2);
        if (c1 != c2) {
            match = 0;
            break;
        }
    }

    if (!is_empty(s1)) || (!is_empty(s2)))) {
        match = 0;
    }

    destroy_stack(s1);
    destroy_stack(s2);

    return match;
}

