#include <arpa/inet.h>

struct Data {
    char CURP[10];
    char celular[10];
    char partido[5];
};

int main() {
    int sockfd;
    struct sockaddr_in servaddr;
    struct Data data;
    char buffer[1024];

    // Initialize data
    strcpy(data.CURP, "A123456");
    strcpy(data.celular, "123456789");
    strcpy(data.partido, "PAN");

    // Create socket
    sockfd = socket(AF_INET, SOCK_STREAM, 0));
    if (sockfd < 0) {
        perror("socket creation failed");
        exit(EXIT_FAILURE);
    }

    // Set server address
    memset(&servaddr, 0, sizeof(servaddr));
    servaddr.sin_family = AF_INET;
    servaddr.sin_port = htons(8080);
    inet_pton(AF_INET, "127.0.0.1", &servaddr.sin_addr);

    // Connect to server
    if (connect(sockfd, (struct sockaddr *)&servaddr), sizeof(servaddr)) < 0) {
        perror("connection failed");
        close(sockfd);
        exit(EXIT_FAILURE);
    }

    // Send data
    if (send(sockfd, &data, sizeof(data)), 0) < 0) {
        perror("send failed");
        close(sockfd);
        exit(EXIT_FAILURE);
    }

    // Receive response
    if (recv(sockfd, buffer, sizeof(buffer)), 0) < 0) {
        perror("recv failed");
        close(sockfd);
        exit(EXIT_FAILURE);
    }

    // Print response
    printf("Server response: %s\n", buffer);

    // Close socket
    close(sockfd);
    return 0;
}

