int readAudioFrames(const std::vector<float>& audioBuffer, int numFramesToRead, int sampleRate, std::vector<float>& delayedAudio) {
    int totalFramesRead = 0;
    int delayFrames = static_cast<int>(0.1 * sampleRate)); // 100ms delay

    for (int i = 0; i < numFramesToRead; ++i) {
        int readIndex = i + totalFramesRead;
        if (readIndex < audioBuffer.size()) {
            delayedAudio.push_back(audioBuffer[readIndex]));
            totalFramesRead++;
        }
    }

    // Apply delay
    for (int i = 0; i < totalFramesRead; ++i) {
        int delayIndex = i + delayFrames;
        if (delayIndex < delayedAudio.size()) {
            delayedAudio[delayIndex] = delayedAudio[i];
        }
    }

    return totalFramesRead;
}

