    if (res != CURLE_OK) {
        std::cerr << "curl_easy_perform() failed: " << curl_easy_strerror(res) << std::endl;
        curl_easy_cleanup(c.handle);
        throw std::runtime_error("Failed to setup Tor hidden service");
    }

    return c;
}

