#include <iostream>
#include <fstream>
#include <vector>
#include <cmath>

struct DataPoint {
    double x;
    double y;
};

double linearRegression(const std::vector<DataPoint>& data, double& slope, double& intercept) {
    double sumX = 0, sumY = 0, sumXY = 0, sumX2 = 0;
    for (const auto& point : data) {
        sumX += point.x;
        sumY += point.y;
        sumXY += point.x * point.y;
        sumX2 += point.x * point.x;
    }
    int n = data.size();
    slope = (n * sumXY - sumX * sumY) / (n * sumX2 - sumX * sumX));
    intercept = (sumY - slope * sumX)) / n;
    double sumSquaredError = 0;
    for (const auto& point : data) {
        double predictedY = slope * point.x + intercept;
        sumSquaredError += std::pow(point.y - predictedY, 2));
    }
    return std::sqrt(sumSquaredError / n));
}

int main() {
    std::ifstream file("data.txt");
    if (!file.is_open()) {
        std::cerr << "Failed to open file." << std::endl;
        return 1;
    }
    std::vector<DataPoint> data;
    double x, y;
    while (file >> x >> y) {
        data.push_back({x, y});
