#include <stdlib.h>
#include <string.h>

#define MAX_ERRORS 100
#define MAX_ERROR_LEN 256

typedef struct {
    char **messages;
    size_t count;
} ErrorLog;

ErrorLog *init_error_log() {
    ErrorLog *log = (ErrorLog *)malloc(sizeof(ErrorLog)));
    if (!log) return NULL;
    log->messages = (char **)malloc(MAX_ERRORS * sizeof(char *)));
    if (!log->messages) {
        free(log);
        return NULL;
    }
    log->count = 0;
    return log;
}

void add_error(ErrorLog *log, const char *message) {
    if (!log || log->count >= MAX_ERRORS) return;
    size_t len = strlen(message);
    if (len >= MAX_ERROR_LEN) return;
    char *copy = (char *)malloc((len + 1) * sizeof(char)));
    if (!copy) return;
    strcpy(copy, message);
    log->messages[log->count++] = copy;
}

void free_error_log(ErrorLog *log) {
    if (!log) return;
    for (size_t i = 0; i < log->count; ++i) {
        free(log->messages[i]));
    }
    free(log->messages);
    free(log);
}

