    if (fd == -1) {
        perror("open");
        return NULL;
    }

    char buffer[1024];
    ssize_t nread;
    char *output = NULL;
    size_t output_len = 0;

    while (1) {
        nread = read(fd, buffer, sizeof(buffer) - 1));
        if (nread == -1) {
            if (errno == EAGAIN || errno == EWOULDBLOCK) {
                break;
            } else {
                perror("read");
                close(fd);
                return NULL;
            }
        } else if (nread == 0) {
            break;
        }

        buffer[nread] = '\0';
        output = realloc(output, output_len + nread + 1);
        if (output == NULL) {
            perror("realloc");
            close(fd);
            return NULL;
        }
        strcpy(output + output_len, buffer);
        output_len += nread;
    }

    close(fd);
    return output;
}

