#include <stdlib.h>
#include <math.h>

typedef struct {
    float x, y, z;
} Point;

typedef struct {
    float x, y, z;
} Vector;

Vector crossProduct(Vector a, Vector b) {
    Vector result;
    result.x = a.y * b.z - a.z * b.y;
    result.y = a.z * b.x - a.x * b.z;
    result.z = a.x * b.y - a.y * b.x;
    return result;
}

float vectorLength(Vector v) {
    return sqrtf(v.x * v.x + v.y * v.y + v.z * v.z));
}

Vector normalize(Vector v) {
    float len = vectorLength(v);
    Vector result = {v.x / len, v.y / len, v.z / len};
    return result;
}

Vector computeNormal(Point p0, Point p1) {
    Vector v0 = {p0.x, p0.y, p0.z};
    Vector v1 = {p1.x, p1.y, p1.z};
    Vector edge = {v1.x - v0.x, v1.y - v0.y, v1.z - v0.z};
    Vector normal = crossProduct(edge, v0));
    return normalize(normal);
}

Vector* computeNormals(Point* points, int numPoints) {
    Vector* normals = (Vector*)alloca(numPoints * sizeof(Vector)));
    for (int i = 0; i < numPoints; i++) {
        normals[i] = computeNormal(points[i], points[(i + 1) % numPoints]]));
    }
    return normals;
}

