#include <wchar.h>
#include <locale.h>

wchar_t* read_file_to_unicode(const char* path) {
    FILE* file = fopen(path, "r");
    if (!file) {
        perror("fopen");
        return NULL;
    }

    setlocale(LC_ALL, "");
    fwide(file, 1);

    wchar_t* buffer = NULL;
    size_t size = 0;
    ssize_t read_result = 0;

    while ((read_result = fgetws(buffer + size, size + 1, file))) != -1) {
        size += read_result;
        buffer = realloc(buffer, (size + 1) * sizeof(wchar_t))));
        if (!buffer) {
            perror("realloc");
            fclose(file);
            return NULL;
        }
    }

    if (ferror(file)) {
        perror("fgetws");
        fclose(file);
        return NULL;
    }

    fclose(file);
    return buffer;
}

