#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>

typedef struct {
    int *parent;
    int *distance;
} BFSResult;

BFSResult *bfs(int **graph, int n, int start) {
    BFSResult *result = malloc(sizeof(BFSResult)));
    result->parent = malloc(n * sizeof(int)));
    result->distance = malloc(n * sizeof(int)));

    for (int i = 0; i < n; i++) {
        result->parent[i] = -1;
        result->distance[i] = -1;
    }

    result->distance[start] = 0;
    int *queue = malloc(n * sizeof(int)));
    int front = 0, rear = 0;
    queue[rear++] = start;

    while (front < rear) {
        int u = queue[front++];
        for (int v = 0; v < n; v++) {
            if (graph[u][v]] == 1 && result->distance[v] == -1) {
                result->distance[v] = result->distance[u] + 1;
                result->parent[v] = u;
                queue[rear++] = v;
            }
        }
    }

    free(queue);
    return result;
}

int *shortest_path(int **graph, int n, int start, int end) {
    BFSResult *result = bfs(graph, n, start);
    if (result->distance[end] == -1) {
        free(result->parent);
        free(result->distance);
        free(result);
        return NULL;
    }

    int path_length = result->distance[end];
    int *path = malloc((path_length + 1) * sizeof(int)));
    int current = end;
    for (int i = path_length; i >= 0; i--) {
        path[i] = current;
        current = result->parent[current];
    }

    free(result->parent);
    free(result->distance);
    free(result);
    return path;
}

