            closedir(dir);
            return -1;
        }
    }

    if (rename(old_name, new_name)) != 0) {
        perror("rename");
        closedir(dir);
        return -1;
    }

    printf("File renamed successfully.\n");
    closedir(dir);
    return 0;
}

