#include <vector>
#include <cmath>

std::vector<std::vector<unsigned char>>> gaussian_filter(const std::vector<std::vector<unsigned char>>>& image, int kernel_size, const std::vector<double>& kernel) {
    int width = image[0].size();
    int height = image.size();
    std::vector<std::vector<unsigned char>>> filtered_image(height, std::vector<unsigned char>(width, 0)));

    for (int y = 0; y < height; ++y) {
        for (int x = 0; x < width; ++x) {
            double sum = 0.0;
            for (int ky = 0; ky < kernel_size; ++ky) {
                for (int kx = 0; kx < kernel_size; ++kx) {
                    int iy = y + ky - kernel_size / 2;
                    int ix = x + kx - kernel_size / 2;
                    if (iy >= 0 && iy < height && ix >= 0 && ix < width) {
                        sum += image[iy][ix]] * kernel[ky * kernel_size + kx];
                    }
                }
            }
            filtered_image[y][x] = static_cast<unsigned char>(std::max(0.0, std::min(255.0, sum))))));
        }
    }

    return filtered_image;
}

