class DisjointSetUnion {
public:
    DisjointSetUnion(int n) : parent(n), rank(n, 0) {
        std::iota(parent.begin(), parent.end(), 0);
    }

    int find(int x) {
        if (parent[x] != x) {
            parent[x] = find(parent[x]);
        }
        return parent[x];
    }

    void unite(int x, int y) {
        int rootX = find(x);
        int rootY = find(y);
        if (rootX != rootY) {
            if (rank[rootX] > rank[rootY]) {
                parent[rootY] = rootX;
            } else if (rank[rootX] < rank[rootY])) {
                parent[rootX] = rootY;
            } else {
                parent[rootY] = rootX;
                rank[rootX]++;
            }
        }
    }

    bool arePairwiseConnected(const std::vector<int>& firstSet, const std::vector<int>& secondSet) {
        for (int x : firstSet) {
            for (int y : secondSet) {
                if (find(x) != find(y)) {
                    return false;
                }
            }
        }
        return true;
    }
};

