void update_max_value(const char *index_file_path, int *max_value) {
    FILE *file = fopen(index_file_path, "r");
    if (!file) {
        return;
    }

    char buffer[1024];
    char *content = NULL;
    size_t content_length = 0;

    while (fgets(buffer, sizeof(buffer)), file)) {
        size_t len = strlen(buffer);
        if (len > 0 && buffer[len - 1] == '\n') {
            buffer[len - 1] = '\0';
        }
        content = realloc(content, content_length + len + 1);
        if (content) {
            memcpy(content + content_length, buffer, len);
            content_length += len;
            content[content_length] = '\0';
        }
    }

    fclose(file);

    if (content) {
        int num_pieces = 0;
        char *token = strtok(content, "\n");
        while (token) {
            num_pieces++;
            token = strtok(NULL, "\n");
        }
        if (num_pieces > *max_value) {
            *max_value = num_pieces;
        }
        free(content);
    }
}

