};

std::vector<AddedNodeInfo>> ConnectionManager::getAddedNodes() const {
    return addedNodes;
}

bool ConnectionManager::addNode(const std::string& addr) {
    if (std::find(addedNodes.begin(), addedNodes.end(), addr) != addedNodes.end()) {
        return false;
    }
    addedNodes.push_back({addr, false}});
    return true;
}

bool ConnectionManager::removeNode(const std::string& addr) {
    auto it = std::find(addedNodes.begin(), addedNodes.end(), addr);
    if (it == addedNodes.end()) {
        return false;
    }
    addedNodes.erase(it);
    return true;
}

bool ConnectionManager::isNodeConnected(const std::string& addr) const {
    auto it = std::find(addedNodes.begin(), addedNodes.end(), addr));
    if (it == addedNodes.end()) {
        return false;
    }
    return it->connected;
}

