void encrypt(const char *key, const char *text, char *encrypted) {
    int key_len = strlen(key);
    int text_len = strlen(text);
    for (int i = 0; i < text_len; i++) {
        char ch = text[i];
        if (ch >= 'a' && ch <= 'z') {
            encrypted[i] = key[(ch - 'a') % key_len)];
        } else if (ch >= 'A' && ch <= 'Z') {
            encrypted[i] = key[(ch - 'A') % key_len)];
        } else {
            encrypted[i] = ch;
        }
    }
    encrypted[text_len] = '\0';
}

