using System.Numerics;

public class ImageDisplacement
{
    private Random random = new Random();

    public double[,] GenerateDisplacementField(int width, int height, double stepSize)
    {
        double[,] displacementField = new double[width, height];

        for (int y = 0; y < height; y++)
        {
            for (int x = 0; x < width; x++)
            {
                double displacementX = GenerateGaussianRandom(stepSize);
                double displacementY = GenerateGaussianRandom(stepSize);

                displacementField[x, y] = displacementX * displacementY;
            }
        }

        return displacementField;
    }

    private double GenerateGaussianRandom(double stepSize)
    {
        double u1 = random.NextDouble();
        double u2 = random.NextDouble();
        double z0 = Math.Sqrt(-2.0 * Math.Log(u1)));
        double z1 = 2.0 * Math.PI * u2;
        double gaussianRandom = z0 * Math.Cos(z1) * stepSize;
        return gaussianRandom;
    }
}

