public static class MatrixGenerator
{
    public static T[,] CreateRandomMatrix<T>(int rows, int cols, Random rand, T minValue, T maxValue) where T : IComparable<T>
    {
        T[,] matrix = new T[rows, cols];
        for (int i = 0; i < rows; i++)
        {
            for (int j = 0; j < cols; j++)
            {
                matrix[i, j] = GenerateRandomValue(rand, minValue, maxValue);
            }
        }
        return matrix;
    }

    private static T GenerateRandomValue<T>(Random rand, T minValue, T maxValue) where T : IComparable<T>
    {
        if (typeof(T) == typeof(int)))
        {
            return (T)(object)rand.Next(((int)minValue), ((int)maxValue) + 1);
        }
        else if (typeof(T) == typeof(double)))
        {
            return (T)(object)rand.NextDouble() * ((double)maxValue - (double)minValue) + (double)minValue;
        }
        throw new NotSupportedException("Type not supported for random generation.");
    }
}

