using System;
using System.Collections.Generic;
using System.Linq;

public static class RandomElementSelector
{
    public static IEnumerable<T> SelectRandomElements<T>(List<T> items, int count)
    {
        if (items == null || items.Count == 0)
        {
            throw new ArgumentException("The list cannot be null or empty.");
        }

        if (count <= 0 || count > items.Count)
        {
            throw new ArgumentException("The count must be a positive integer and less than or equal to the number of items in the list.");
        }

        Random random = new Random();
        HashSet<int> selectedIndices = new HashSet<int>();

        while (selectedIndices.Count < count)
        {
            int randomIndex = random.Next(items.Count);
            if (!selectedIndices.Contains(randomIndex))
            {
                selectedIndices.Add(randomIndex);
            }
        }

        foreach (int index in selectedIndices)
        {
            yield return items[index];
        }
    }
}

