    {
        Random random = new Random();
        int index = random.Next(shards.Count);
        Shard selectedShard = shards[index];

        T result = await operation(selectedShard);

        if (result is null)
        {
            throw new InvalidOperationException("Operation result cannot be null.");
        }

        bool isIntegrityValid = await VerifyIntegrityAsync(result);

