using System;
using System.Data;
using System.Data.SqlClient;
using System.Text.Json;

public class ResourceUpdater
{
    private readonly string _connectionString;

    public ResourceUpdater(string connectionString)
    {
        _connectionString = connectionString;
    }

    public string UpdateResource(int resourceId, string requestBody)
    {
        try
        {
            using (SqlConnection connection = new SqlConnection(_connectionString)))
            {
                connection.Open();

                // Validate request body
                var request = JsonSerializer.Deserialize<ResourceRequest>(requestBody));
                if (request == null || string.IsNullOrEmpty(request.Name))
                {
                    return JsonSerializer.Serialize(new { error = "Invalid request body" } ));
                }

                // Update resource in database
                string updateQuery = "UPDATE Resources SET Name = @Name, Description = @Description WHERE Id = @Id";
                using (SqlCommand command = new SqlCommand(updateQuery, connection)))
                {
                    command.Parameters.AddWithValue("@Id", resourceId);
                    command.Parameters.AddWithValue("@Name", request.Name);
                    command.Parameters.AddWithValue("@Description", request.Description ?? string.Empty);

                    int rowsAffected = command.ExecuteNonQuery();
                    if (rowsAffected == 0)
                    {
                        return JsonSerializer.Serialize(new { error = "Resource not found" } ));
                    }
                }

                // Return updated resource
                string selectQuery = "SELECT Id, Name, Description FROM Resources WHERE Id = @Id";
                using (SqlCommand command = new SqlCommand(selectQuery, connection)))
                {
                    command.Parameters.AddWithValue("@Id", resourceId);
                    using (SqlDataReader reader = command.ExecuteReader())
                    {
                        if (reader.Read())
                        {
                            var updatedResource = new
                            {
                                Id = reader.GetInt32(0)),
                                Name = reader.GetString(1),
                                Description = reader.GetString(2)
                            };
                            return JsonSerializer.Serialize(updatedResource);
                        }
                    }
                }
            }
        }
        catch (Exception ex)
        {
            return JsonSerializer.Serialize(new { error = "Database error: " + ex.Message } ));
        }
    }
}

public class ResourceRequest
{
    public string Name { get; set; }
    public string Description { get; set; }
}

