public class CassandraBatchStatementTest
{
    [Fact]
    public async Task TestBatchStatement()
    {
        var cluster = Cluster.Builder()
            .AddContactPoint("127.0.0.1")
            .Build();

        var session = cluster.Connect("test");

        var batch = new BatchStatement();

        var insert = new SimpleStatement(
            "INSERT INTO users (id, name, email) VALUES (?, ?, ?)",
            Guid.NewGuid(), "John Doe", "john.doe@example.com"
        );

        batch.Add(insert);

        var outgoingPayload = new Dictionary<byte[], byte[]>
        {
            { new byte[] { 1, 2, 3 } }, new byte[] { 4, 5, 6 } }
        };

        batch.SetOutgoingPayload(outgoingPayload);

        await session.ExecuteAsync(batch);

        var incomingPayload = batch.GetIncomingPayload();

        Assert.NotNull(incomingPayload);
        Assert.Equal(outgoingPayload.Count, incomingPayload.Count);

        foreach (var kvp in outgoingPayload)
        {
            Assert.True(incomingPayload.ContainsKey(kvp.Key)));
            Assert.Equal(kvp.Value, incomingPayload[kvp.Key]]);
        }
    }
}

