using System.Linq;
using System.Threading;
using System.Threading.Tasks;

class Program
{
    static async Task Main(string[] args)
    {
        int numberOfIterations = 1000;
        int numberOfThreads = 10;
        int rangeStart = 1;
        int rangeEnd = 1000;
        int timeoutMilliseconds = 5000;

        for (int i = 0; i < numberOfIterations; i++)
        {
            var tasks = new List<Task>();

            for (int j = 0; j < numberOfThreads; j++)
            {
                int randomNumber = rangeStart + new Random().Next(rangeEnd - rangeStart + 1));
                tasks.Add(ConsumeAsync(randomNumber, timeoutMilliseconds)));
            }

            await Task.WhenAll(tasks);
        }
    }

    static async Task ConsumeAsync(int number, int timeoutMilliseconds)
    {
        using (var cts = new CancellationTokenSource(timeoutMilliseconds)))
        {
            try
            {
                await Task.Delay(100, cts.Token));
                Console.WriteLine($"Processed number: {number}");
            }
            catch (TaskCanceledException)
            {
                Console.WriteLine($"Operation timed out for number: {number}");
            }
        }
    }
}

