public void StartProcessWithSentinel(ProcessStartInfo startInfo, string trackingFolder, int timeoutSeconds)
{
    if (!Directory.Exists(trackingFolder)))
    {
        throw new InvalidOperationException("Tracking folder does not exist.");
    }

    Process process = new Process();
    process.StartInfo = startInfo;
    process.Start();

    string trackingFilePath = Path.Combine(trackingFolder, process.Id.ToString() + ".txt"));
    File.WriteAllText(trackingFilePath, process.Id.ToString());

    Process sentinelProcess = new Process();
    sentinelProcess.StartInfo.FileName = "sentinel.exe";
    sentinelProcess.StartInfo.Arguments = $"{process.Id} {trackingFilePath} {timeoutSeconds}";
    sentinelProcess.Start();
}

