public Font CreateFont(Device device, string fontName)
{
    Assembly assembly = Assembly.GetExecutingAssembly();
    Stream stream = assembly.GetManifestResourceStream("FontResources." + fontName + ".xml");
    XmlDocument xmlDoc = new XmlDocument();
    xmlDoc.Load(stream);
    XmlNode node = xmlDoc.SelectSingleNode("//font");
    float size = float.Parse(node.SelectSingleNode("@size").Value);
    string family = node.SelectSingleNode("@family").Value;
    FontStyle style = FontStyle.Regular;
    XmlNode styleNode = node.SelectSingleNode("@style");
    if (styleNode != null)
    {
        string styleStr = styleNode.Value;
        if (styleStr.Contains("Bold")))
        {
            style |= FontStyle.Bold;
        }
        if (styleStr.Contains("Italic")))
        {
            style |= FontStyle.Italic;
        }
    }
    return new Font(family, size, style);
}

