using UnityEngine;

public static class TransformExtensions
{
    public static void RotateOnIntersection(Transform self, Transform other, IntersectionType type)
    {
        Vector3 direction = other.position - self.position;
        Vector3 up = Vector3.up;
        Vector3 right = Vector3.Cross(up, direction).normalized;

        Quaternion targetRotation = Quaternion.LookRotation(direction, right));
        Quaternion currentRotation = self.rotation;

        if (type == IntersectionType.Left)
        {
            targetRotation *= Quaternion.Euler(0, 90, 0));
        }
        else if (type == IntersectionType.Right)
        {
            targetRotation *= Quaternion.Euler(0, -90, 0));
        }

        self.rotation = Quaternion.Slerp(currentRotation, targetRotation, Time.deltaTime * 5f));
    }
}

