public static T CreateAndSaveInstance<T>(T inputObject, DbContext context) where T : class, new()
{
    var newObject = new T();
    var inputType = inputObject.GetType();
    var newType = newObject.GetType();

    foreach (var property in inputType.GetProperties())
    {
        var newProperty = newType.GetProperty(property.Name);
        if (newProperty != null && newProperty.CanWrite)
        {
            newProperty.SetValue(newObject, property.GetValue(inputObject)));
        }
    }

    newObject.Id = inputObject.Id;
    context.Set<T>().Add(newObject);
    context.SaveChanges();
    return newObject;
}

