using System;
using System.IO;
using System.Collections.Generic;
using System.Linq;
using System.Text.RegularExpressions;

public class IniFileReader
{
    public static Dictionary<string, Dictionary<string, string>>> ReadIniFiles(string[] filePaths)
    {
        var iniFiles = new Dictionary<string, Dictionary<string, string>>>>();

        foreach (var filePath in filePaths)
        {
            try
            {
                var iniData = new Dictionary<string, Dictionary<string, string>>>>();
                var sections = File.ReadAllLines(filePath).Where(l => !string.IsNullOrWhiteSpace(l) && !l.StartsWith(";") && !l.StartsWith("#"))).GroupBy(l => l.TrimStart('['), ']')).ToList();

                foreach (var section in sections)
                {
                    var options = section.ToList().Skip(1).Select(l => l.Trim().Split(new[] { '=' }, StringSplitOptions.None))).ToDictionary(kvp => kvp.Key.Trim(), kvp => kvp.Value.Trim());
                    iniData[section.Key] = options;
                }

                iniFiles[filePath] = iniData;
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Error reading ini file '{filePath}': {ex.Message}");
            }
        }

        return iniFiles;
    }
}

