using Microsoft.AspNetCore.Mvc;
using System.Collections.Generic;
using System.Linq;

namespace MyApplication.Controllers
{
    [ApiController]
    [Route("api/[controller]")]
    public class MyController : ControllerBase
    {
        private readonly MyDbContext _context;

        public MyController(MyDbContext context)
        {
            _context = context;
        }

        [HttpGet("{id}")]
        public IActionResult Get(int id)
        {
            var model = LoadModel<MyModel>(id);
            if (model == null)
            {
                return NotFound();
            }
            return Ok(model);
        }

        [HttpPost]
        public IActionResult Post([FromBody] MyModel model)
        {
            if (!ModelState.IsValid)
            {
                return BadRequest(ModelState);
            }
            _context.MyModels.Add(model);
            _context.SaveChanges();
            return CreatedAtAction(nameof(Get), new { id = model.Id }), model);
        }

        [HttpPut("{id}")]
        public IActionResult Put(int id, [FromBody] MyModel model)
        {
            if (id != model.Id)
            {
                return BadRequest();
            }
            if (!ModelState.IsValid)
            {
                return BadRequest(ModelState);
            }
            _context.Entry(model).State = EntityState.Modified;
            _context.SaveChanges();
            return NoContent();
        }

        private T LoadModel<T>(int id) where T : class
        {
            var type = typeof(T);
            var tableName = type.Name;
            var query = $"SELECT * FROM {tableName} WHERE Id = {id}";
            var result = _context.Database.SqlQueryRaw<T>(query).FirstOrDefault();
            return result;
        }
    }
}

