using System;
using System.Diagnostics;
using System.Text;

public class CommandLineExecutor
{
    public static int ExecuteProcess(string fileName, string arguments, Action<string> outputCallback, Action<string> errorCallback)
    {
        using (Process process = new Process())
        {
            process.StartInfo.FileName = fileName;
            process.StartInfo.Arguments = arguments;
            process.StartInfo.RedirectStandardOutput = true;
            process.StartInfo.RedirectStandardError = true;
            process.StartInfo.UseShellExecute = false;
            process.StartInfo.CreateNoWindow = true;

            process.OutputDataReceived += (sender, e) => outputCallback?.Invoke(e.Data);
            process.ErrorDataReceived += (sender, e) => errorCallback?.Invoke(e.Data);

            process.Start();
            process.BeginOutputReadLine();
            process.BeginErrorReadLine();

            process.WaitForExit();

            return process.ExitCode;
        }
    }
}

