    {
        using (SqlConnection connection = new SqlConnection(connectionString))
        {
            connection.Open();

            // Check if the author has permission to create a post
            string permissionCheckQuery = "SELECT COUNT(*) FROM UserPermissions WHERE UserId = @authorId AND Permission = 'CreateBlogPost'";
            using (SqlCommand permissionCheckCommand = new SqlCommand(permissionCheckQuery, connection))
            {
                permissionCheckCommand.Parameters.AddWithValue("@authorId", authorId);
                int permissionCount = (int)permissionCheckCommand.ExecuteScalar();
                if (permissionCount == 0)
                {
                    throw new UnauthorizedAccessException("The author does not have permission to create a blog post.");
                }
            }

            // Insert the new blog post into the database
            string insertQuery = "INSERT INTO BlogPosts (Title, Content, AuthorId, CreatedAt) VALUES (@title, @content, @authorId, GETDATE())";
            using (SqlCommand insertCommand = new SqlCommand(insertQuery, connection))
            {
                insertCommand.Parameters.AddWithValue("@title", title);
                insertCommand.Parameters.AddWithValue("@content", content);
                insertCommand.Parameters.AddWithValue("@authorId", authorId);
                insertCommand.ExecuteNonQuery();
            }

            // Notify the editor about the new blog post
            string notifyEditorQuery = "INSERT INTO EditorNotifications (BlogPostId, NotificationType, SentAt) VALUES ((SELECT TOP 1 Id FROM BlogPosts WHERE AuthorId = @authorId ORDER BY CreatedAt DESC)), 'NewPost', GETDATE())";
