public class ProcessExecutor
{
    public static int ExecuteProcess(string path, string arguments, Action<string> outputCallback, Action<string> errorCallback)
    {
        Process process = new Process();
        process.StartInfo.FileName = path;
        process.StartInfo.Arguments = arguments;
        process.StartInfo.RedirectStandardOutput = true;
        process.StartInfo.RedirectStandardError = true;
        process.StartInfo.UseShellExecute = false;
        process.OutputDataReceived += (sender, e) => outputCallback(e.Data);
        process.ErrorDataReceived += (sender, e) => errorCallback(e.Data);
        process.Start();
        process.BeginOutputReadLine();
        process.BeginErrorReadLine();
        process.WaitForExit();
        return process.ExitCode;
    }
}

