using System;
using System.Xml;
using System.Reflection;

public class XmlGenerator
{
    public static XmlDocument GenerateXml(Type type)
    {
        XmlDocument xmlDoc = new XmlDocument();
        XmlElement root = xmlDoc.CreateElement("Type");
        root.SetAttribute("Name", type.Name);
        xmlDoc.AppendChild(root);

        object[] attributes = type.GetCustomAttributes(true);
        foreach (object attribute in attributes)
        {
            Type attrType = attribute.GetType();
            XmlElement attrElement = xmlDoc.CreateElement(attrType.Name);
            PropertyInfo[] props = attrType.GetProperties();
            foreach (PropertyInfo prop in props)
            {
                XmlElement propElement = xmlDoc.CreateElement(prop.Name);
                propElement.InnerText = prop.GetValue(attribute)?.ToString() ?? string.Empty;
                attrElement.AppendChild(propElement);
            }
            root.AppendChild(attrElement);
        }

        return xmlDoc;
    }
}

