    using (var stream = assembly.GetManifestResourceStream(resourceName)))
    {
        if (stream != null)
        {
            using (var reader = new StreamReader(stream)))
            {
                var html = reader.ReadToEnd();
                var doc = new HtmlDocument();
                doc.LoadHtml(html);

                var geocacheNodes = doc.DocumentNode.SelectNodes("//div[@class='geocache']");

                if (geocacheNodes != null)
                {
                    foreach (var node in geocacheNodes)
                    {
                        var coordinates = node.SelectSingleNode(".//span[@class='coordinates']']").InnerText;
                        var dateLogged = DateTime.Parse(node.SelectSingleNode(".//span[@class='date']']").InnerText);
                        items.Add(new TravelItem { Coordinates = coordinates, DateLogged = dateLogged }));
                    }
                }
            }
        }
    }

    return items;
}

