CREATE OR REPLACE FUNCTION insert_villain(
    @name TEXT,
    @evilnessFactor INT,
    @connection TEXT,
    @transaction TEXT
) RETURNS INT AS $$
DECLARE
    last_insert_id INT;
BEGIN
    -- Establish connection and begin transaction
    EXECUTE format('CONNECT TO %I', @connection);
    EXECUTE format('BEGIN TRANSACTION %I', @transaction);

    -- Insert new villain
    EXECUTE format('INSERT INTO Villains (name, evilness_factor) VALUES (%L, %L) RETURNING id', @name, @evilnessFactor)
    INTO last_insert_id;

    -- Commit transaction
    EXECUTE format('COMMIT TRANSACTION %I', @transaction);

    -- Return last inserted ID
    RETURN last_insert_id;
EXCEPTION
    WHEN OTHERS THEN
        -- Rollback transaction on error
        EXECUTE format('ROLLBACK TRANSACTION %I', @transaction);
        RAISE;
END;
$$ LANGUAGE plpgsql;

