    protected override void OnKeyDown(KeyEventArgs e)
    {
        base.OnKeyDown(e);
        if (e.Control && (e.KeyCode == Keys.Left || e.KeyCode == Keys.Right)))
        {
            EnableHyperlinks(!Enabled);
        }
    }

    private void EnableHyperlinks(bool enable)
    {
        foreach (var link in FindHyperlinks())
        {
            link.Enabled = enable;
        }
