    private string[] FindHyperlinks()
    {
        var links = new System.Collections.Generic.List<string>();
        for (int i = 0; i < Text.Length; i++)
        {
            if (Text[i] == 'h' && i + 7 < Text.Length && Text.Substring(i, 8) == "http://")
            {
                links.Add(Text.Substring(i, 8)));
                i += 7;
            }
        }
        return links.ToArray();
    }

