using System.Diagnostics;
using System.IO;

public class FileCopier
{
    public static void CopyFiles(string sourceDir, string targetDir, string[] includeExtensions, string[] excludeExtensions)
    {
        if (!Directory.Exists(targetDir))
        {
            Directory.CreateDirectory(targetDir);
        }

        string[] files = Directory.GetFiles(sourceDir);

        foreach (string file in files)
        {
            string fileName = Path.GetFileName(file);
            string fileExtension = Path.GetExtension(fileName);

            bool include = Array.Exists(includeExtensions, ext => ext.Equals(fileExtension, StringComparison.OrdinalIgnoreCase))));
            bool exclude = Array.Exists(excludeExtensions, ext => ext.Equals(fileExtension, StringComparison.OrdinalIgnoreCase))));

            if (include && !exclude)
            {
                string targetFilePath = Path.Combine(targetDir, fileName));
                File.Copy(file, targetFilePath, true);
            }
        }
    }
}

