using System.Net.Http;
using System.Threading.Tasks;

class Program
{
    static async Task Main(string[] args)
    {
        try
        {
            Process process = new Process();
            process.StartInfo.FileName = "external_executable.exe";
            process.StartInfo.Arguments = "arg1 arg2";
            process.Start();
            process.WaitForExit();

            string result = await CallRemoteServiceAsync();
            Console.WriteLine("Remote service result: " + result);
        }
        catch (Exception ex)
        {
            Console.WriteLine("Error: " + ex.Message);
        }
    }

    static async Task<string> CallRemoteServiceAsync()
    {
        int retries = 3;
        TimeSpan delay = TimeSpan.FromSeconds(2);

        for (int i = 0; i < retries; i++)
        {
            try
            {
                using (HttpClient client = new HttpClient())
                {
                    HttpResponseMessage response = await client.GetAsync("https://api.example.com/data");
                    response.EnsureSuccessStatusCode();
                    string result = await response.Content.ReadAsStringAsync();
                    return result;
                }
            }
            catch (Exception ex)
            {
                Console.WriteLine("Remote service call failed (attempt " + (i + 1)) + "): " + ex.Message);
                if (i < retries - 1)
                {
                    await Task.Delay(delay);
                }
            }
        }

        throw new Exception("Failed to call remote service after " + retries + " attempts.");
    }
}

