    byte[] key = Encoding.ASCII.GetBytes("0123456789ABC");
    byte[] iv = Encoding.ASCII.GetBytes("0123456");
    byte[] encrypted = Convert.FromBase64String(hexEncrypted);

    using (DESCryptoServiceProvider des = new DESCryptoServiceProvider())
    {
        des.Key = key;
        des.IV = iv;
        des.Mode = CipherMode.CBC;
        des.Padding = PaddingMode.PKCS7;

