        {
            using (CryptoStream cs = new CryptoStream(ms, des.CreateDecryptor()), CryptoStreamMode.Read))
            {
                using (StreamReader sr = new StreamReader(cs)))
                {
                    return sr.ReadToEnd();
                }
            }
        }
    }
}

