    public static void ExtractTextFromPdf(string inputPdfPath, string outputPdfPath)
    {
        using (var pdfDoc = new PdfDocument(new PdfReader(inputPdfPath))))
        {
            using (var tesseract = new TesseractEngine(@"./tessdata", "eng", EngineMode.Default)))
            {
                for (int i = 1; i <= pdfDoc.GetNumberOfPages(); i++)
                {
                    var page = pdfDoc.GetPage(i);
                    using (var bitmap = page.GetBitmap())
                    {
                        using (var pageText = tesseract.Process(bitmap))
                        {
                            var document = new Document();
                            var writer = PdfWriter.GetInstance(document, new FileStream(outputPdfPath, FileMode.Append), FileAccess.Write));
                            document.Open();
                            document.Add(new Paragraph(pageText.GetText())));
                            document.Close();
                        }
                    }
                }
            }
        }
        Process.Start(outputPdfPath);
    }
}

