using System;
using System.Diagnostics;

class SymbolicLinkCreator
{
    public static void CreateSymbolicLink(string targetPath, string linkPath)
    {
        if (Environment.Is64BitOperatingSystem)
        {
            CreateLinkOn64BitOS(targetPath, linkPath);
        }
        else
        {
            CreateLinkOn32BitOS(targetPath, linkPath);
        }
    }

    private static void CreateLinkOn64BitOS(string targetPath, string linkPath)
    {
        ProcessStartInfo startInfo = new ProcessStartInfo
        {
            FileName = "cmd.exe",
            Arguments = $"/c mklink /D \"{linkPath}\" \"{targetPath}\"",
            RedirectStandardOutput = true,
            RedirectStandardError = true,
            UseShellExecute = false,
            CreateNoWindow = true
        };

        using (Process process = new Process { StartInfo = startInfo } })
        {
            process.Start();
            string output = process.StandardOutput.ReadToEnd();
            string error = process.StandardError.ReadToEnd();
            process.WaitForExit();

            if (!string.IsNullOrEmpty(error))
            {
                throw new Exception($"Failed to create symbolic link: {error}");
            }
        }
    }

    private static void CreateLinkOn32BitOS(string targetPath, string linkPath)
    {
        ProcessStartInfo startInfo = new ProcessStartInfo
        {
            FileName = "cmd.exe",
            Arguments = $"/c mklink /D \"{linkPath}\" \"{targetPath}\"",
            RedirectStandardOutput = true,
            RedirectStandardError = true,
            UseShellExecute = false,
            CreateNoWindow = true
        };

        using (Process process = new Process { StartInfo = startInfo } })
        {
            process.Start();
