using System;
using System.IO;
using System.Xml.Linq;

public class ConfigManager
{
    public static void UpdateConfig(string configPath, string systemNode, Dictionary<string, string> updates)
    {
        if (!File.Exists(configPath))
        {
            throw new FileNotFoundException("Configuration file not found.");
        }

        XDocument configDoc = XDocument.Load(configPath);
        XElement systemSettings = configDoc.Element("Configuration").Element(systemNode);

        if (systemSettings == null)
        {
            throw new ArgumentException("System settings node not found.");
        }

        foreach (var update in updates)
        {
            systemSettings.Element(update.Key)?.SetValue(update.Value);
        }

        configDoc.Save(configPath);
    }
}

