public class EncryptionTest
{
    public static void TestEncryption(SymmetricAlgorithm algorithm, byte[] key, byte[] iv, byte[] plaintext)
    {
        algorithm.Key = key;
        algorithm.IV = iv;

        ICryptoTransform encryptor = algorithm.CreateEncryptor();
        byte[] encrypted = encryptor.TransformFinalBlock(plaintext, 0, plaintext.Length));

        ICryptoTransform decryptor = algorithm.CreateDecryptor();
        byte[] decrypted = decryptor.TransformFinalBlock(encrypted, 0, encrypted.Length));

        Console.WriteLine("Key Size: " + algorithm.KeySize);
        Console.WriteLine("Effective Key Size: " + algorithm.LegalKeySizes[0].MaxSize);
        Console.WriteLine("Block Size: " + algorithm.BlockSize);

        Console.WriteLine("Plaintext: " + Convert.ToBase64String(plaintext)));
        Console.WriteLine("Encrypted: " + Convert.ToBase64String(encrypted)));
        Console.WriteLine("Decrypted: " + Convert.ToBase64String(decrypted)));

        Console.WriteLine("Encryption and decryption are inverse operations.");
        Console.WriteLine("The encrypted message is the same as the original plaintext message.");
    }
}

