        Field field2 = doc2.getField(fieldName);

        if (field1 == null || field2 == null) {
            throw new IllegalArgumentException("Field '" + fieldName + "' not found in one or both documents.");
        }

        if (field1.fieldType().numericType() != field2.fieldType().numericType()) {
            throw new IllegalArgumentException("Numeric types of field '" + fieldName + "' do not match.");
