        if (field1.numericValue().longValue() != field2.numericValue().longValue()) {
            MatcherAssert.assertThat("Values of field '" + fieldName + "' do not match.", field1.numericValue().longValue(), Matchers.equalTo(field2.numericValue().longValue())));
        }
    }
}

