import java.util.Random;

public class PairProcessor {
    private static final Random RANDOM = new Random();

    public static void processPairs(List<Pair> pairs, double percentage) {
        int targetCount = (int) (pairs.size() * percentage);
        int count = 0;

        for (int i = 0; i < pairs.size(); i++) {
            Pair currentPair = pairs.get(i);
            System.out.println("Processing pair: " + currentPair + " (last: " + (i == pairs.size() - 1) + "))");

            if (i < pairs.size() - 1) {
                int randomIndex = RANDOM.nextInt(i);
                Pair previousPair = pairs.get(randomIndex);
                System.out.println("Moving pair to position: " + randomIndex + " (previous pair: " + previousPair + "))");
                pairs.set(randomIndex, currentPair);
                pairs.set(i, previousPair);
            }

            count++;
            if (count >= targetCount) {
                break;
            }
        }
    }

    public static class Pair {
        private final int value;
        private final boolean flag;

        public Pair(int value, boolean flag) {
            this.value = value;
            this.flag = flag;
        }

        @Override
        public String toString() {
            return "(" + value + ", " + flag + ")";
        }
    }
}

