import java.util.Random;

public class BinaryFileGenerator {

    public static String generateRandomBinaryFile(FileSystem fs, String folder, String fileName, int length) throws IOException {
        Random random = new Random();
        byte[] buffer = new byte[length];

        for (int i = 0; i < length; i++) {
            if (random.nextBoolean()) {
                buffer[i] = (byte) random.nextInt(256);
            } else {
                byte[] temp = new byte[random.nextInt(10) + 1)];
                random.nextBytes(temp);
                System.arraycopy(temp, 0, buffer, i, temp.length);
                i += temp.length - 1;
            }
        }

        String filePath = fs.joinPath(folder, fileName));
        try (FileOutputStream fos = new FileOutputStream(filePath)) {
            fos.write(buffer);
        }

        return filePath;
    }
}

