import java.lang.reflect.Field;
import java.util.ArrayList;
import java.util.List;

public class JsonGenerator {
    public static String generateJson(Object obj) throws IllegalAccessException {
        StringBuilder json = new StringBuilder();
        json.append("{");

        Class<?> clazz = obj.getClass();
        Field[] fields = clazz.getDeclaredFields();

        for (int i = 0; i < fields.length; i++) {
            Field field = fields[i];
            field.setAccessible(true);

            json.append("\"").append(field.getName()).append("\":");
            json.append(generateJsonValue(field.get(obj))));

            if (i < fields.length - 1) {
                json.append(",");
            }
        }

        json.append("}");
        return json.toString();
    }

    private static String generateJsonValue(Object value) {
        if (value == null) {
            return "null";
        } else if (value instanceof String) {
            return "\"" + value.toString().replace("\"", "\\\"")) + "\"";
        } else if (value instanceof Number || value instanceof Boolean) {
            return value.toString();
        } else if (value instanceof List) {
            List<?> list = (List<?>) value;
            StringBuilder json = new StringBuilder();
            json.append("[");

            for (int i = 0; i < list.size(); i++) {
                json.append(generateJsonValue(list.get(i))));

                if (i < list.size() - 1) {
                    json.append(",");
                }
            }

            json.append("]");
            return json.toString();
        } else if (value instanceof Object) {
            return generateJson(value);
        }

        return "null";
    }
}

