    public static <T> Map<T, Double> normalizeWeights(
            List<T> items, Function<T, Double> weightFunc) {
        Map<T, Double> weights = new HashMap<>();
        double totalWeight = 0;
        for (T item : items) {
            double weight = weightFunc.apply(item);
            weights.put(item, weight);
            totalWeight += weight;
