import java.util.Arrays;

public class DisjointPairs {
    public static int countDisjointPairs(int[] arr) {
        int n = arr.length;
        int[] parent = new int[n];
        for (int i = 0; i < n; i++) {
            parent[i] = i;
        }
        int count = 0;
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                long startTime = System.currentTimeMillis();
                int rootI = find(parent, i);
                int rootJ = find(parent, j);
                boolean disjoint = rootI != rootJ;
                long endTime = System.currentTimeMillis();
                System.out.println("Pair (" + arr[i] + ", " + arr[j] + ") is disjoint: " + disjoint + " (Time: " + (endTime - startTime) + " ms)");
                if (disjoint) {
                    count++;
                    union(parent, rootI, rootJ);
                }
            }
        }
        return count;
    }

    private static int find(int[] parent, int i) {
        if (parent[i] != i) {
            parent[i] = find(parent, parent[i]);
        }
        return parent[i];
    }

    private static void union(int[] parent, int i, int j) {
        int rootI = find(parent, i);
        int rootJ = find(parent, j);
        if (rootI != rootJ) {
            parent[rootI] = rootJ;
        }
    }

    public static void main(String[] args) {
        int[] arr = {1, 2, 3, 4, 5};
        int count = countDisjointPairs(arr);
        System.out.println("Total disjoint pairs: " + count);
    }
}

