public RectF getCroppedDrawable(RectF drawableBounds, RectF viewport) {
    Random random = new Random();
    float drawableAspectRatio = drawableBounds.width() / drawableBounds.height();
    float viewportAspectRatio = viewport.width() / viewport.height();
    float cropAspectRatio = drawableAspectRatio > viewportAspectRatio ? drawableAspectRatio : viewportAspectRatio;
    float cropWidth = Math.min(drawableBounds.width(), viewport.width() * cropAspectRatio));
    float cropHeight = cropWidth / cropAspectRatio;
    float cropLeft = drawableBounds.left + (drawableBounds.width() - cropWidth) * random.nextFloat());
    float cropTop = drawableBounds.top + (drawableBounds.height() - cropHeight) * random.nextFloat());
    return new RectF(cropLeft, cropTop, cropLeft + cropWidth, cropTop + cropHeight);
}

