import java.util.List;
import java.util.stream.Collectors;

public class GeographicalPointComparator {

    public static void assertEqualWithinDistance(List<Point> points1, List<Point> points2, double distanceTolerance) {
        if (points1.size() != points2.size()) {
            throw new AssertionError("Number of points in both sets must be equal");
        }

        List<Point> sortedPoints1 = points1.stream().sorted().collect(Collectors.toList());
        List<Point> sortedPoints2 = points2.stream().sorted().collect(Collectors.toList());

        for (int i = 0; i < sortedPoints1.size(); i++) {
            Point point1 = sortedPoints1.get(i);
            Point point2 = sortedPoints2.get(i);

            if (point1.distanceTo(point2) > distanceTolerance) {
                throw new AssertionError("Points at index " + i + " are not equal within distance tolerance");
            }
        }
    }
}

class Point implements Comparable<Point> {
    private double latitude;
    private double longitude;

    public Point(double latitude, double longitude) {
        this.latitude = latitude;
        this.longitude = longitude;
    }

    public double getLatitude() {
        return latitude;
    }

    public double getLongitude() {
        return longitude;
    }

    public double distanceTo(Point other) {
        double earthRadius = 6371.0;
        double lat1 = Math.toRadians(this.getLatitude());
        double lon1 = Math.toRadians(this.getLongitude());
        double lat2 = Math.toRadians(other.getLatitude());
        double lon2 = Math.toRadians(other.getLongitude());

        double dlon = lon2 - lon1;
        double dlat = lat2 - lat1;
        double a = Math.sin(dlat / 2) * Math.sin(dlat / 2) +
                      Math.cos(lat1) * Math.cos(lat2) *
                      Math.sin(dlon / 2) * Math.sin(dlon / 2));
        double c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a))));
        double distance = earthRadius * c;
        return distance;
    }

    @Override
    public int compareTo(Point other) {
        int latComparison = Double.compare(this.getLatitude(), other.getLatitude());
        if (latComparison != 0) {
            return latComparison;
        }
        return Double.compare(this.getLongitude(), other.getLongitude());
    }
}

