public boolean verifyToken(String tokenId) {
    DelegationToken token = tokenManager.getToken(tokenId);
    return token != null && !token.isExpired();
}

public DelegationToken renewToken(String tokenId) {
    DelegationToken token = tokenManager.getToken(tokenId);
    if (token != null && !token.isExpired()) {
        token.setExpirationTime(System.currentTimeMillis() + 86400000L));
        tokenManager.storeToken(token);
        return token;
    }
    return null;
}

public boolean cancelToken(String tokenId) {
    DelegationToken token = tokenManager.getToken(tokenId);
    if (token != null) {
        tokenManager.removeToken(tokenId);
        return true;
    }
    return false;
}

