import javax.crypto.KeyGenerator;
import javax.crypto.SecretKey;
import javax.crypto.spec.CTRModeParameterSpec;
import java.security.SecureRandom;

public class AESCTR {
    public static void main(String[] args) throws Exception {
        String algorithm = "AES";
        int keySize = 256;
        String input = "Hello, World!";

        SecretKey key = generateKey(algorithm, keySize);
        byte[] encrypted = encrypt(input.getBytes(), key);

        System.out.println("Encrypted: " + bytesToHex(encrypted)));
    }

    private static SecretKey generateKey(String algorithm, int keySize) throws Exception {
        KeyGenerator keyGen = KeyGenerator.getInstance(algorithm);
        keyGen.init(keySize, new SecureRandom());
        return keyGen.generateKey();
    }

    private static byte[] encrypt(byte[] plaintext, SecretKey key) throws Exception {
        Cipher cipher = Cipher.getInstance("AES/CTR/NoPadding");
        byte[] iv = new byte[16];
        new SecureRandom().nextBytes(iv);
        CTRModeParameterSpec ctrSpec = new CTRModeParameterSpec(iv);
        cipher.init(Cipher.ENCRYPT_MODE, key, ctrSpec);
        return cipher.doFinal(plaintext);
    }

    private static String bytesToHex(byte[] bytes) {
        StringBuilder sb = new StringBuilder();
        for (byte b : bytes) {
            sb.append(String.format("%02x", b)));
        }
        return sb.toString();
    }
}

