import java.time.LocalDate;
import java.time.format.DateTimeFormatter;
import java.util.Base64;

public class DateRangeProcessor {
    public static String processDateRange(String input) {
        String[] parts = input.split("/");
        LocalDate startDate = LocalDate.parse(parts[0], DateTimeFormatter.ISO_LOCAL_DATE));
        LocalDate endDate = LocalDate.parse(parts[1], DateTimeFormatter.ISO_LOCAL_DATE));
        String interval = startDate + "/" + endDate;
        String hash = Base64.getEncoder().encodeToString(interval.getBytes()));
        return hash + interval;
    }
}

