public class URLValidator {

    public static List<InetSocketAddress> validateAndResolveURLs(List<String> urls) {
        List<InetSocketAddress> addresses = new ArrayList<>();
        for (String url : urls) {
            try {
                URI uri = new URI(url);
                String host = uri.getHost();
                int port = uri.getPort();
                if (host == null || host.isEmpty()) {
                    throw new URISyntaxException(url, "Missing host");
                }
                if (port == -1) {
                    throw new URISyntaxException(url, "Missing port");
                }
                addresses.add(new InetSocketAddress(host, port)));
            } catch (URISyntaxException e) {
                System.err.println("Invalid URL: " + url + " - " + e.getMessage());
            }
        }
        return addresses;
    }
}

