import java.io.*;
import java.util.*;

public class HMMTagger {
    private Map<String, Map<String, Double>>> transition;
    private Map<String, Map<String, Double>>> emission;
    private Map<String, Double> initial;

    public HMMTagger(String modelFile) throws IOException {
        BufferedReader reader = new BufferedReader(new FileReader(modelFile)));
        String line;
        transition = new HashMap<>();
        emission = new HashMap<>();
        initial = new HashMap<>();

        while ((line = reader.readLine()) != null) {
            String[] parts = line.split("\\s+");
            String type = parts[0];
            String from = parts[1];
            String to = parts[2];
            double prob = Double.parseDouble(parts[3]));

            if (type.equals("transition"))) {
                transition.computeIfAbsent(from, k -> new HashMap<>()).put(to, prob);
            } else if (type.equals("emission"))) {
                emission.computeIfAbsent(from, k -> new HashMap<>()).put(to, prob);
            } else if (type.equals("initial"))) {
                initial.put(from, prob);
            }
        }
        reader.close();
    }

    public Map<String, String> tagText(String text) {
        String[] words = text.split("\\s+");
        Map<String, String> tagged = new HashMap<>();

        for (String word : words) {
            double maxProb = 0;
            String bestTag = null;

            for (String tag : emission.getOrDefault(word, new HashMap<>()))) {
                double prob = emission.get(word).get(tag);
                if (initial.containsKey(tag)) {
                    prob *= initial.get(tag);
                }
                if (prob > maxProb) {
                    maxProb = prob;
                    bestTag = tag;
                }
            }
            tagged.put(word, bestTag);
        }
        return tagged;
    }

    public static void main(String[] args) throws IOException {
        HMMTagger tagger = new HMMTagger("hmm_model.txt");
        String text = "The quick brown fox jumps over the lazy dog";
        Map<String, String> tagged = tagger.tagText(text);
        System.out.println(tagged);
    }
}

