import java.io.*;
import java.net.*;
import java.util.zip.*;

public Response sendPostRequest(String endpoint, String requestBody, String token, int maxRate) throws IOException {
    URL url = new URL(endpoint);
    HttpURLConnection connection = (HttpURLConnection) url.openConnection();
    connection.setRequestMethod("POST");
    connection.setRequestProperty("Authorization", "Bearer " + token);
    connection.setRequestProperty("Content-Type", "application/json");
    connection.setDoOutput(true);

    if (maxRate > 0) {
        RateLimiter rateLimiter = RateLimiter.create(maxRate);
        rateLimiter.acquire();
    }

    try (OutputStream os = connection.getOutputStream()) {
        byte[] input = requestBody.getBytes("utf-8");
        if (input.length > 1024) {
            try (GZIPOutputStream gzip = new GZIPOutputStream(os)) {
                gzip.write(input);
            }
        } else {
            os.write(input, 0, input.length);
        }
    }

    try (BufferedReader br = new BufferedReader(new InputStreamReader(connection.getInputStream(), "utf-8")))) {
        StringBuilder response = new StringBuilder();
        String responseLine = null;
        while ((responseLine = br.readLine()) != null) {
            response.append(responseLine.trim());
        }
        return new Response(connection.getResponseCode(), response.toString()));
    }
}

class Response {
    private int statusCode;
    private String body;

    public Response(int statusCode, String body) {
        this.statusCode = statusCode;
        this.body = body;
    }

    public int getStatusCode() {
        return statusCode;
    }

    public String getBody() {
        return body;
    }
}

