import java.io.File;
import java.io.FileInputStream;
import java.io.FileOutputStream;
import java.security.MessageDigest;
import java.util.zip.DeflaterOutputStream;

public class FileCompressor {
    public static String compressFile(String filePath, int level) throws Exception {
        File file = new File(filePath);
        FileInputStream fis = new FileInputStream(file);
        FileOutputStream fos = new FileOutputStream(file + ".lzo"));
        DeflaterOutputStream dos = new DeflaterOutputStream(fos, new java.util.zip.Deflater(level)));
        byte[] buffer = new byte[1024 * 1024];
        int bytesRead;
        while ((bytesRead = fis.read(buffer)) != -1) {
            dos.write(buffer, 0, bytesRead);
        }
        dos.close();
        fis.close();
        fos.close();
        return calculateMD5(file + ".lzo"));
    }

    private static String calculateMD5(File file) throws Exception {
        MessageDigest md = MessageDigest.getInstance("MD5");
        FileInputStream fis = new FileInputStream(file);
        byte[] buffer = new byte[1024 * 1024]];
        int bytesRead;
        while ((bytesRead = fis.read(buffer)) != -1) {
            md.update(buffer, 0, bytesRead);
        }
        fis.close();
        byte[] digest = md.digest();
        StringBuilder sb = new StringBuilder();
        for (byte b : digest) {
            sb.append(String.format("%02x", b)));
        }
        return sb.toString();
    }
}

