public class SerializationBenchmark {
    public static void main(String[] args) throws IOException, ClassNotFoundException {
        int iterations = 500;
        ByteArrayOutputStream baos = new ByteArrayOutputStream();
        ObjectOutputStream oos = new ObjectOutputStream(baos);
        ObjectInputStream ois = new ObjectInputStream(new ByteArrayInputStream(baos.toByteArray())));

        Random random = new Random();
        List<Integer> data = new ArrayList<>();
        for (int i = 0; i < 1000; i++) {
            data.add(random.nextInt(10000)));
        }

        long totalSerializationTime = 0;
        long totalDeserializationTime = 0;
        long totalSerializedSize = 0;

        for (int i = 0; i < iterations; i++) {
            long startTime = System.nanoTime();
            oos.writeObject(data);
            long endTime = System.nanoTime();
            totalSerializationTime += (endTime - startTime);

            startTime = System.nanoTime();
            List<Integer> deserializedData = (List<Integer>) ois.readObject();
            endTime = System.nanoTime();
            totalDeserializationTime += (endTime - startTime);

            totalSerializedSize += baos.size();
            baos.reset();
        }

        System.out.println("Average Serialization Time: " + (totalSerializationTime / iterations)) + " ns";
        System.out.println("Average Deserialization Time: " + (totalDeserializationTime / iterations)) + " ns";
        System.out.println("Average Serialized Size: " + (totalSerializedSize / iterations)) + " bytes");
    }
}

