import java.io.*;
import java.util.*;
import javax.xml.parsers.*;
import org.w3c.dom.*;
import org.xml.sax.*;

public class DataExtractor {
    public static void main(String[] args) {
        List<File> files = new ArrayList<>();
        files.add(new File("data1.xml")));
        files.add(new File("data2.json")));
        files.add(new File("data3.csv")));

        for (File file : files) {
            try {
                Object data = parseFile(file);
                System.out.println("Extracted data from " + file.getName() + ":");
                System.out.println(data);
                System.out.println();
            } catch (Exception e) {
                System.err.println("Error processing file " + file.getName() + ":");
                e.printStackTrace();
                System.err.println();
            }
        }
    }

    private static Object parseFile(File file) throws Exception {
        String fileName = file.getName();
        if (fileName.endsWith(".xml"))) {
            return parseXML(file);
        } else if (fileName.endsWith(".json"))) {
            return parseJSON(file);
        } else if (fileName.endsWith(".csv"))) {
            return parseCSV(file);
        } else {
            throw new IllegalArgumentException("Unsupported file format: " + fileName);
        }
    }

    private static Object parseXML(File file) throws Exception {
        DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();
        DocumentBuilder builder = factory.newDocumentBuilder();
        Document document = builder.parse(file);
        document.getDocumentElement().normalize();
        return document;
    }

    private static Object parseJSON(File file) throws Exception {
        BufferedReader reader = new BufferedReader(new FileReader(file)));
        StringBuilder jsonBuilder = new StringBuilder();
        String line;
        while ((line = reader.readLine()) != null) {
            jsonBuilder.append(line);
        }
        reader.close();
        return jsonBuilder.toString();
    }

    private static Object parseCSV(File file) throws Exception {
        BufferedReader reader = new BufferedReader(new FileReader(file)));
        List<String[]> rows = new ArrayList<>();
        String line;
        while ((line = reader.readLine()) != null) {
            String[] columns = line.split(",");
            rows.add(columns);
        }
        reader.close();
        return rows;
    }
}

