public int executeCommand(InputStream inputStream, OutputStream outputStream, Optional<Long> timeout) throws IOException, InterruptedException {
    Process process = Runtime.getRuntime().exec("your_command_here");

    if (inputStream != null) {
        inputStream.transferTo(process.getOutputStream());
    }

    if (outputStream != null) {
        process.getInputStream().transferTo(outputStream);
    }

    if (timeout.isPresent()) {
        if (!process.waitFor(timeout.get(), TimeUnit.MILLISECONDS))) {
            process.destroyForcibly();
            throw new TimeoutException("Command execution timed out");
        }
    } else {
        process.waitFor();
    }

    return process.exitValue();
}

