import java.io.*;

public class NFA {
    private int windowLength;
    private boolean[][] transitionTable;

    public NFA(int windowLength) {
        this.windowLength = windowLength;
        this.transitionTable = new boolean[windowLength][256]];
    }

    public NFA clone() {
        try {
            ByteArrayOutputStream bos = new ByteArrayOutputStream();
            ObjectOutputStream oos = new ObjectOutputStream(bos);
            oos.writeObject(this);
            oos.close();
            ByteArrayInputStream bis = new ByteArrayInputStream(bos.toByteArray());
            ObjectInputStream ois = new ObjectInputStream(bis);
            NFA cloned = (NFA) ois.readObject();
            ois.close();
            return cloned;
        } catch (IOException | ClassNotFoundException e) {
            throw new RuntimeException("Failed to clone NFA", e);
        }
    }

    public boolean equals(Object obj) {
        if (this == obj) return true;
        if (obj == null || getClass() != obj.getClass()) return false;
        NFA nfa = (NFA) obj;
        return windowLength == nfa.windowLength &&
               Arrays.deepEquals(transitionTable, nfa.transitionTable);
    }
}

