public class ServiceController {
    private static final ScheduledExecutorService scheduler = Executors.newScheduledThreadPool(1);
    private static final Random random = new Random();
    private static boolean isServiceRunning = false;

    public static void main(String[] args) {
        startService();
    }

    private static void startService() {
        if (!isServiceRunning) {
            isServiceRunning = true;
            System.out.println("Service started at " + System.currentTimeMillis());
            int delay = random.nextInt(10000) + 10000; // 10-20 seconds
            scheduler.schedule(() -> stopService(), delay, TimeUnit.MILLISECONDS);
        }
    }

    private static void stopService() {
        if (isServiceRunning) {
            isServiceRunning = false;
            System.out.println("Service stopped at " + System.currentTimeMillis());
            sendMessageToMessagingSystem("Service stopped");
        }
    }

    private static void sendMessageToMessagingSystem(String message) {
        // Code to send message to messaging system
        System.out.println("Message sent to messaging system: " + message);
    }
}

