import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;

public class MessageEncryptor {
    public static String encryptMessage(String message, String encoding, boolean toUpperCase) throws NoSuchAlgorithmException {
        MessageDigest md = MessageDigest.getInstance("MD5");
        byte[] messageBytes = message.getBytes(encoding);
        byte[] encryptedBytes = md.digest(messageBytes);
        String encryptedMessage = bytesToHex(encryptedBytes);
        return toUpperCase ? encryptedMessage.toUpperCase() : encryptedMessage;
    }

    private static String bytesToHex(byte[] bytes) {
        StringBuilder hexString = new StringBuilder();
        for (byte b : bytes) {
            String hex = Integer.toHexString(0xff & b);
            if (hex.length() == 1) hexString.append('0');
            hexString.append(hex);
        }
        return hexString.toString();
    }
}

