import java.io.File;
import java.io.FileInputStream;
import java.io.IOException;
import java.net.HttpURLConnection;
import java.net.URL;
import java.util.concurrent.TimeUnit;

public class FileUploader {

    public static boolean uploadFile(String remoteUrl, File file) throws IOException {
        int maxRetries = 3;
        for (int attempt = 1; attempt <= maxRetries; attempt++) {
            try (FileInputStream fis = new FileInputStream(file)) {
                URL url = new URL(remoteUrl);
                HttpURLConnection connection = (HttpURLConnection) url.openConnection();
                connection.setDoOutput(true);
                connection.setRequestMethod("PUT");
                connection.setConnectTimeout(5000);
                connection.setReadTimeout(5000);
                connection.getOutputStream().write(fis.readAllBytes()));
                int responseCode = connection.getResponseCode();
                if (responseCode == HttpURLConnection.HTTP_CREATED || responseCode == HttpURLConnection.HTTP_NO_CONTENT) {
                    return true;
                }
            } catch (IOException e) {
                if (attempt == maxRetries) {
                    throw e;
                }
                TimeUnit.SECONDS.sleep(2 * attempt);
            }
        }
        return false;
    }
}

