import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;

public class HexConverter {
    public static char[] convertToHex(byte[] byteArray) throws NoSuchAlgorithmException {
        MessageDigest md = MessageDigest.getInstance("MD5");
        byte[] hashBytes = md.digest(byteArray);
        char[] hexChars = new char[hashBytes.length * 2]];
        for (int i = 0; i < hashBytes.length; i++) {
            int v = hashBytes[i] & 0xFF;
            hexChars[i * 2] = (char) (v / 16 + '0'));
            hexChars[i * 2 + 1] = (char) (v % 16 + '0'));
        }
        return hexChars;
    }
}

