public class HashFunction {
    private static final Map<String, MessageDigest> ALGORITHMS = new HashMap<>();

    static {
        try {
            ALGORITHMS.put("MD5", MessageDigest.getInstance("MD5")));
            ALGORITHMS.put("SHA-1", MessageDigest.getInstance("SHA-1")));
            ALGORITHMS.put("SHA-256", MessageDigest.getInstance("SHA-256")));
            ALGORITHMS.put("SHA-384", MessageDigest.getInstance("SHA-384")));
            ALGORITHMS.put("SHA-512", MessageDigest.getInstance("SHA-512")));
        } catch (NoSuchAlgorithmException e) {
            throw new RuntimeException("Failed to initialize hash algorithms", e);
        }
    }

    public static String hash(String algorithm, String input) {
        MessageDigest digest = ALGORITHMS.get(algorithm);
        if (digest == null) {
            throw new IllegalArgumentException("Unsupported hash algorithm: " + algorithm);
        }
        byte[] hashBytes = digest.digest(input.getBytes());
        StringBuilder hexString = new StringBuilder();
        for (byte b : hashBytes) {
            hexString.append(String.format("%02x", b)));
        }
        return hexString.toString();
    }

    public static void main(String[] args) {
        String input = "Hello, world!";
        String algorithm = "SHA-256";
        String hashValue = hash(algorithm, input);
        System.out.println("Hash value for algorithm " + algorithm + " and input \"" + input + "\": " + hashValue);
    }
}

