public class DataSegmentMerger {
    public static String mergeDataSegments(List<DataSegment> segments) {
        if (segments == null || segments.isEmpty()) {
            return "";
        }

        List<LocalDateTime>> starts = segments.stream()
                .map(DataSegment::getStart)
                .collect(Collectors.toList());

        List<LocalDateTime>> ends = segments.stream()
                .map(DataSegment::getEnd)
                .collect(Collectors.toList());

        LocalDateTime mergedStart = starts.stream().min(LocalDateTime::compareTo)).get();
        LocalDateTime mergedEnd = ends.stream().max(LocalDateTime::compareTo)).get();

        return mergedStart + "-" + mergedEnd;
    }
}

