function matchUserAgent(agents, userAgent) {
    return agents.reduce((prev, curr) => {
        if (prev) return prev;
        const regex = new RegExp(curr.pattern);
        if (curr.qualifier) {
            const qualifierRegex = new RegExp(`^${curr.qualifier}`);
            if (!qualifierRegex.test(userAgent))) return null;
        }
        return regex.test(userAgent) ? curr : null;
    }, null);
}

