const fs = require('fs');
const path = require('path');
const less = require('less');

function compileLessFiles(directory) {
    const compiledFiles = {};

    function processFile(filePath) {
        const fileExtension = path.extname(filePath).toLowerCase();

        if (fileExtension === '.less') {
            fs.readFile(filePath, 'utf8', (err, data) => {
                if (err) {
                    console.error(`Error reading file ${filePath}:`, err);
                    return;
                }

                less.render(data, { filename: filePath }), (err, output) => {
                    if (err) {
                        console.error(`Error compiling Less file ${filePath}:`, err);
                        return;
                    }

                    const cssFilePath = filePath.replace(/\.less$/, '.css');
                    fs.writeFile(cssFilePath, output.css, 'utf8', (err) => {
                        if (err) {
                            console.error(`Error writing CSS file ${cssFilePath}:`, err);
                            return;
                        }

                        compiledFiles[cssFilePath] = filePath;
                        console.log(`Compiled ${filePath} to ${cssFilePath}`);
                    }));
                });
            }));
        }
    }

    function processDirectory(dirPath) {
        fs.readdir(dirPath, (err, files) => {
            if (err) {
                console.error(`Error reading directory ${dirPath}:`, err);
                return;
            }

            files.forEach((file) => {
                const filePath = path.join(dirPath, file));
                fs.stat(filePath, (err, stats) => {
                    if (err) {
                        console.error(`Error getting stats for file ${filePath}:`, err);
                        return;
                    }

                    if (stats.isDirectory()) {
                        processDirectory(filePath);
                    } else {
                        processFile(filePath);
                    }
                }));
            });
        }));
    }

    processDirectory(directory);
    return compiledFiles;
}

