const path = require('path');
const _ = require('lodash');

const filesToDelete = ['temp.txt', 'cache.json'];
const filesToInsert = ['header.html', 'footer.html'];
const sassFiles = ['styles.scss', 'components.scss'];
const tsFiles = ['app.ts', 'utils.ts'];
const concatFiles = ['part1.txt', 'part2.txt', 'part3.txt'];

filesToDelete.forEach(file => {
    fs.unlinkSync(path.join(__dirname, file)));
});

filesToInsert.forEach(file => {
    const content = fs.readFileSync(path.join(__dirname, 'template.html'))).toString();
    fs.writeFileSync(path.join(__dirname, file)), content);
});

sassFiles.forEach(file => {
    const sass = require('sass');
    const result = sass.compile(path.join(__dirname, file))));
    fs.writeFileSync(path.join(__dirname, file.replace('.scss', '.css')))), result.css.toString());
});

tsFiles.forEach(file => {
    const ts = require('typescript');
    const result = ts.transpileModule(fs.readFileSync(path.join(__dirname, file)))), { compilerOptions: { module: ts.ModuleKind.CommonJS } } });
    fs.writeFileSync(path.join(__dirname, file.replace('.ts', '.js'))))), result.outputText);
});

const concatContent = concatFiles.map(file => fs.readFileSync(path.join(__dirname, file)))), { separator: '\n' }).toString();
fs.writeFileSync(path.join(__dirname, 'concatenated.txt'))), concatContent);

