        return attrValue === value;
    } else if (operator === '!=' || operator === '!==') {
        return attrValue !== value;
    } else if (operator === '>=' || operator === '>=') {
        return attrValue >= value;
    } else if (operator === '<=' || operator === '<=') {
        return attrValue <= value;
    }
    return false;
}

