function loadDataFromFiles(filePaths, callback) {
    const data = {};
    let completed = 0;

    filePaths.forEach((filePath, index) => {
        fs.readFile(filePath, 'utf8', (err, content) => {
            if (err) {
                return callback(err);
            }
            data[filePath] = content;
            completed++;

            if (completed === filePaths.length) {
                callback(null, data);
            }
        });
    });
}

module.exports = loadDataFromFiles;

