const { execSync } = require('child_process');
const fs = require('fs');
const path = require('path');

function cloneAndLink(repoUrl, targetDir, execPath) {
    const repoName = path.basename(repoUrl, '.git'));
    const clonePath = path.join(targetDir, repoName));

    try {
        execSync(`git clone ${repoUrl} ${clonePath}`);
        const execLink = path.join(targetDir, execPath));
        fs.symlinkSync(path.join(clonePath, 'bin', 'executable'))), execLink);
        console.log(`Repository cloned and executable linked to ${execLink}`);
    } catch (error) {
        console.error(`Error cloning repository or linking executable: ${error.message}`);
    }
}

// Example usage:
