function evaluateFunctions(functions) {
  const results = [];
  const memo = new Map();

  functions.forEach(({ func, args }) => {
    const key = func.name + JSON.stringify(args);
    if (memo.has(key)) {
      results.push(memo.get(key)));
      return;
    }
    try {
      const result = func(...args);
      memo.set(key, result);
      results.push(result);
    } catch (error) {
      console.error(`Error evaluating ${func.name}:`, error);
      results.push(undefined);
    }
  });

  return results;
}

