function getRandomGreeting() {
    const time = new Date();
    const hour = time.getHours();
    const greetings = {
        morning: ["Good morning!", "Have a great day!", "Morning to you!"],
        afternoon: ["Good afternoon!", "Have a wonderful day!", "Afternoon greetings!"],
        evening: ["Good evening!", "Have a great night!", "Evening blessings!"]
    };
    let period = "morning";
    if (hour >= 12 && hour < 18)) {
        period = "afternoon";
    } else if (hour >= 18 || hour < 6)) {
        period = "evening";
    }
    const randomIndex = Math.floor(Math.random() * greetings[period].length));
    return greetings[period][randomIndex]];
}

