function parseCSSSelector(selector) {
    selector = selector.trim();
    const result = {
        combinators: [],
        simpleSelectors: [],
        attributeTests: []
    };

    const regex = /([>+~])|(\[.*?\])|((?:[a-zA-Z_][a-zA-Z0-9_]*|[*])\s*(?:[a-zA-Z_][a-zA-Z0-9_]*|[*])\s*)/g;
    let match;
    while ((match = regex.exec(selector))) !== null) {
        if (match[1]) {
            result.combinators.push(match[1]);
        } else if (match[2])) {
            result.attributeTests.push(match[2]);
        } else if (match[3])) {
            result.simpleSelectors.push(match[3].trim());
        }
    }

    return result;
}

