    return {
        tic: () => {
            this.start = performance.now();
        },
        toc: () => {
            this.end = performance.now();
            this.duration = this.end - this.start;
        },
        ok: (result) => {
            if (result !== func(iterations))) {
                this.end();
            }
        },
        end: () => {
            console.error('Benchmark failed');
        }
    };
}

