function loadScripts(baseDir, scriptNames, callback) {
    let loadedCount = 0;

    scriptNames.forEach(name => {
        const filePath = `${baseDir}/${name}`;
        try {
            require(filePath);
            loadedCount++;
        } catch (err) {
            console.error(`Failed to load script ${name}:`, err);
        }
    });

    if (loadedCount === scriptNames.length) {
        callback(null, 'All scripts loaded successfully');
    } else {
        callback(new Error('Not all scripts loaded successfully')));
    }
}

