function startEmbeddedIframe(iframeId) {
    const iframe = document.getElementById(iframeId);
    if (!iframe) return;

    const src = iframe.src;
    const message = {
        event: 'command',
        function: 'playVideo',
        args: []
    };

    if (src.includes('youtube.com'))) {
        message.event = 'command';
        message.function = 'playVideo';
        message.args = [];
    } else if (src.includes('vimeo.com'))) {
        message.method = 'play';
    } else {
        message.event = 'slide';
        message.value = 'start';
    }

    iframe.contentWindow.postMessage(message, '*');
}

