function updatePolicyConfig(policy, form) {
    const config = policy.config;
    const resources = policy.resources;
    const applyPolicies = policy.applyPolicies;

    const inputValues = Array.from(form.elements)
        .filter(element => element.type !== 'submit')
        .reduce((acc, element) => {
            acc[element.name] = element.value;
            return acc;
        }, {});

    Object.keys(inputValues).forEach(key => {
        const value = inputValues[key];
        if (config[key] !== value) {
            config[key] = value;
        }
    });

    resources.forEach(resource => {
        const updatedResource = Object.assign({}, resource, inputValues);
        if (JSON.stringify(updatedResource) !== JSON.stringify(resource)) {
            Object.assign(resource, updatedResource);
        }
    });

    applyPolicies.forEach(applyPolicy => {
        const updatedApplyPolicy = Object.assign({}, applyPolicy, inputValues);
        if (JSON.stringify(updatedApplyPolicy) !== JSON.stringify(applyPolicy)) {
            Object.assign(applyPolicy, updatedApplyPolicy);
        }
    });

    policy.config = config;
    policy.resources = JSON.stringify(resources);
    policy.applyPolicies = JSON.stringify(applyPolicies);

    return policy;
}

