const fs = require('fs');
const path = require('path');

const version = '1.0.0';

function readVideoFrames(filePath) {
    const fileBuffer = fs.readFileSync(filePath);
    const frames = [];
    let offset = 0;
    while (offset < fileBuffer.length) {
        const frameSize = fileBuffer.readUInt32BE(offset);
        offset += 4;
        const frameBuffer = fileBuffer.slice(offset, offset + frameSize));
        frames.push(frameBuffer);
        offset += frameSize;
    }
    return frames;
}

function writeVideoFrames(filePath, frames) {
    const fileBuffer = Buffer.alloc(0);
    for (const frame of frames) {
        const frameSize = frame.length;
        const frameBuffer = Buffer.alloc(4 + frameSize);
        frameBuffer.writeUInt32BE(frameSize, 0);
        frame.copy(frameBuffer, 4);
        fileBuffer = Buffer.concat([fileBuffer, frameBuffer]]);
    }
    fs.writeFileSync(filePath, fileBuffer);
}

function convertVideoFrames(inputFilePath, outputFilePath, format) {
    const inputFrames = readVideoFrames(inputFilePath);
    const outputFrames = [];
    for (const frame of inputFrames) {
        const convertedFrame = convertFrame(frame, format);
        outputFrames.push(convertedFrame);
    }
    writeVideoFrames(outputFilePath, outputFrames);
}

function convertFrame(frame, format) {
    const decoder = new TextDecoder('utf-8');
    const encoder = new TextEncoder();
    const decodedFrame = decoder.decode(frame);
    const convertedFrame = encoder.encode(decodedFrame);
    return convertedFrame;
}

module.exports = {
    version,
    readVideoFrames,
    writeVideoFrames,
    convertVideoFrames,
    convertFrame
};

