function enableDragResize(element, alignButtons) {
    let isDragging = false;
    let isResizing = false;
    let initialX, initialY, initialWidth, initialHeight;

    element.addEventListener('mousedown', (e) => {
        initialX = e.clientX;
        initialY = e.clientY;
        initialWidth = element.offsetWidth;
        initialHeight = element.offsetHeight;

        if (e.target === alignButtons[0])) {
            element.style.left = '0px';
        } else if (e.target === alignButtons[1])) {
            element.style.left = `${window.innerWidth - element.offsetWidth}px`;
        }

        isDragging = true;
    }));

    document.addEventListener('mousemove', (e) => {
        if (isDragging) {
            element.style.left = `${element.offsetLeft + e.clientX - initialX}px`;
            element.style.top = `${element.offsetTop + e.clientY - initialY}px`;
        }
    }));

    document.addEventListener('mouseup', () => {
        isDragging = false;
    }));

    element.addEventListener('mousedown', (e) => {
        if (e.target === element.querySelector('.resize-handle'))) {
            initialWidth = element.offsetWidth;
            initialHeight = element.offsetHeight;
            isResizing = true;
        }
    }));

    document.addEventListener('mousemove', (e) => {
        if (isResizing) {
            const deltaX = e.clientX - initialX;
            const deltaY = e.clientY - initialY;
            element.style.width = `${initialWidth + deltaX}px`;
            element.style.height = `${initialHeight + deltaY}px`;
        }
    }));

    document.addEventListener('mouseup', () => {
        isResizing = false;
    }));
}

