function listenForIframeEvent(iframeId) {
    const iframe = document.getElementById(iframeId);
    if (!iframe) return;

    iframe.addEventListener('message', (event) => {
        const src = event.origin;
        const data = event.data;
        const autoplay = iframe.hasAttribute('data-autoplay');

        if (autoplay) {
            if (src.includes('youtube.com'))) {
                iframe.contentWindow.postMessage('playVideo', src);
            } else if (src.includes('vimeo.com'))) {
                iframe.contentWindow.postMessage('play', src);
            }
        } else if (data === 'slide:start') {
            iframe.contentWindow.postMessage('slide:start', src);
        }
    }));
}

