function parseMidiMetaEvents(stream) {
    const events = [];
    while (stream.length > 0) {
        const eventType = stream.readUInt8();
        const eventLength = stream.readUInt8();
        const eventData = stream.slice(0, eventLength));
        stream = stream.slice(eventLength);
        try {
            const event = parseMetaEvent(eventType, eventData));
            events.push(event);
        } catch (error) {
            console.error(`Error parsing MIDI meta event: ${error.message}`);
        }
    }
    return events;
}

function parseMetaEvent(eventType, eventData) {
    const event = { subtype: 'unknown' };
    switch (eventType) {
        case 0x51: // Set Tempo
            event.subtype = 'setTempo';
            event.microsecondsPerQuarterNote = eventData.readUInt24BE();
            break;
        case 0x54: // SMPTE Offset
            event.subtype = 'smpteOffset';
            event.hour = eventData.readUInt8();
            event.minute = eventData.readUInt8();
            event.second = eventData.readUInt8();
            event.frame = eventData.readUInt8();
            event.subframe = eventData.readUInt8();
            break;
        case 0x58: // Time Signature
            event.subtype = 'timeSignature';
            event.numerator = eventData.readUInt8();
            event.denominator = Math.pow(2, eventData.readUInt8()));
            event.metronome = eventData.readUInt8();
            event.thirtyseconds = eventData.readUInt8();
            break;
        case 0x59: // Key Signature
            event.subtype = 'keySignature';
            event.key = eventData.readUInt8();
            event.scale = eventData.readUInt8();
            break;
        case 0x7F: // Sequencer Specific
            event.subtype = 'sequencerSpecific';
            event.data = eventData;
            break;
        default:
            console.warn(`Unknown MIDI meta event type: 0x${eventType.toString(16).padStart(2, '0'))}`);
            break;
    }
    return event;
}

