import java.lang.reflect.Method;
import java.util.ArrayList;
import java.util.List;

public class MethodFilter {
    public static List<Method> filterMethods(List<Class<?>> classes, String methodName, Class<?> interfaceClass, boolean isAbstract, Class<?> annotationClass) {
        List<Method> filteredMethods = new ArrayList<>();
        for (Class<?> clazz : classes) {
            for (Method method : clazz.getDeclaredMethods()) {
                if (methodName != null && !methodName.equals(method.getName())) {
                    continue;
                }
                if (interfaceClass != null && !interfaceClass.isAssignableFrom(clazz)) {
                    continue;
                }
                if (isAbstract && !java.lang.reflect.Modifier.isAbstract(method.getModifiers()))) {
                    continue;
                }
                if (annotationClass != null && !method.isAnnotationPresent(annotationClass)) {
                    continue;
                }
                filteredMethods.add(method);
            }
        }
        return filteredMethods;
    }
}

