        return CACHE[key]
    base_url = f"https://api.example.com/{name}"
    query_params = {k: v for k, v in params.items() if v is not None}
    full_url = f"{base_url}?{urllib.parse.urlencode(query_params, doseq=True))}"
    if absolute:
        full_url = requests.utils.requote_uri(full_url)
    CACHE[key] = full_url
