function createInteractiveMap(locations) {
    const map = new google.maps.Map(document.getElementById('map')), {
        zoom: 10,
        center: { lat: 37.7749, lng: -122.4194 } // San Francisco
    });

    const categoryMenu = document.getElementById('category-menu');
    const categoryOptions = Array.from(new Set(locations.map(location => location.category)))) // Get unique categories
        .map(category => `<option value="${category}">${category}</option>`).join('');
    categoryMenu.innerHTML = categoryOptions;

    categoryMenu.addEventListener('change', (event) => {
        const selectedCategory = event.target.value;
        const markers = document.querySelectorAll('.map-marker');
        markers.forEach(marker => {
            const category = marker.getAttribute('data-category');
            if (category === selectedCategory) {
                marker.style.display = 'block';
            } else {
                marker.style.display = 'none';
            }
        });
    }));

    locations.forEach(location => {
        const marker = new google.maps.Marker({
            position: { lat: location.latitude, lng: location.longitude } ,
            map: map,
            title: location.name,
            icon: location.category === 'Restaurant' ? 'restaurant.png' : 'default.png',
            dataCategory: location.category
        });
        marker.addListener('click', () => {
            window.open(location.url, '_blank');
        }));
    });
}

