function initPlacesAutocomplete(inputId) {
    const input = $('#' + inputId);
    const options = {
        componentRestrictions: { country: 'us' } },
        fields: ['name', 'place_id', 'geometry.location'],
        strictBounds: false
    };
    const service = new google.maps.places.PlacesService(input[0]));
    const autocomplete = new google.maps.places.Autocomplete(input[0]), options);
    autocomplete.addListener('place_changed', function() {
        const place = autocomplete.getPlace();
        if (!place.geometry) {
            return;
        }
        input.val(place.name);
    });
}

