function initMap(locations) {
    var mapOptions = {
        center: new google.maps.LatLng(37.7749, -122.4194)),
        zoom: 12
    };
    var map = new google.maps.Map(document.getElementById('map')), mapOptions);
    var masonry = new Masonry('#map-container', {
        itemSelector: '.map-item',
        gutter: 10
    }));
    locations.forEach(function(location) {
        var marker = new google.maps.Marker({
            position: new google.maps.LatLng(location.lat, location.lng)),
            map: map,
            label: location.name
        });
        var infoWindow = new google.maps.InfoWindow({
            content: '<div class="map-info"><h3>' + location.name + '</h3><p>' + location.description + '</p><a href="https://www.google.com/maps/search/?api=1&query=' + location.lat + ',' + location.lng + '">Get Directions</a></div>'
        });
        marker.addListener('click', function() {
            infoWindow.open(map, marker);
        });
        masonry.appended(document.createElement('div')));
    });
}

