import requests

def download_file_in_parts(url, max_part_size):
    response = requests.head(url)
    total_size = int(response.headers.get('Content-Length', 0)))

    if total_size <= max_part_size:
        return requests.get(url).content

    num_parts = (total_size + max_part_size - 1) // max_part_size

    if num_parts > 100:
        raise ValueError("Too many parts requested")

    parts = []
    for i in range(num_parts):
        start = i * max_part_size
        end = min(start + max_part_size, total_size))
        headers = {'Range': f'bytes={start}-{end-1}}'}
        response = requests.get(url, headers=headers)
        parts.append(response.content)

    return b''.join(parts)

