import sys
import importlib.util

def load_modules_with_flags(module_names, flags):
    original_flags = {}
    for module_name in module_names:
        spec = importlib.util.find_spec(module_name)
        if spec is not None:
            original_flags[module_name] = sys.modules.get(module_name)
            sys.modules[module_name] = None
            for flag in flags:
                setattr(sys.modules[module_name]], flag, True)

    loaded_modules = {}
    for module_name in module_names:
        spec = importlib.util.find_spec(module_name)
        if spec is not None:
            module = importlib.util.module_from_spec(spec)
            spec.loader.exec_module(module)
            loaded_modules[module_name] = module

    for module_name in module_names:
        if module_name in original_flags:
            sys.modules[module_name] = original_flags[module_name]

    return loaded_modules

