def capture_screenshots(device_id, output_dir, interval=5):
    if not os.path.exists(output_dir):
        os.makedirs(output_dir)

    while True:
        try:
            screenshot_path = os.path.join(output_dir, f'screenshot_{int(time.time())}).png'))
            subprocess.run(['adb', '-s', device_id, 'shell', 'screencap', '-p', screenshot_path], check=True)
            print(f'Screenshot saved to {screenshot_path}')
        except subprocess.CalledProcessError as e:
            print(f'Error capturing screenshot: {e}')
            break
        except Exception as e:
            print(f'Unexpected error: {e}')
            break
        time.sleep(interval)

def read_and_parse_logcat(device_id, output_file, interval=5):
    try:
        with open(output_file, 'w') as f:
            while True:
                try:
                    logcat_output = subprocess.run(['adb', '-s', device_id, 'logcat', '-d'], capture_output=True, text=True, check=True).stdout
                    f.write(logcat_output)
                    f.flush()
                    print(f'Logcat data written to {output_file}')
                except subprocess.CalledProcessError as e:
                    print(f'Error reading logcat: {e}')
                    break
                except Exception as e:
                    print(f'Unexpected error: {e}')
                    break
                time.sleep(interval)
    except Exception as e:
        print(f'Error writing logcat data: {e}')
        return False
    return True

