def generate_reticulation_report(input_dir, output_file, coefficient):
    report = []
    alignment_files = []

    for root, dirs, files in os.walk(input_dir):
        for file in files:
            if file.endswith('.aln'):
                alignment_files.append(os.path.join(root, file)))

    for alignment_file in alignment_files:
        with open(alignment_file, 'r') as f:
            lines = f.readlines()

        reticulations = 0
        taxa = 0
        increase = 0
        decrease = 0
        outgroup = ''

        for line in lines:
            if line.startswith('Reticulations:'):
                reticulations = int(line.split(': ')[1]))
            elif line.startswith('Taxa:'):
                taxa = int(line.split(': ')[1]))
            elif line.startswith('Increase:'):
                increase = int(line.split(': ')[1])) * coefficient
            elif line.startswith('Decrease:'):
                decrease = int(line.split(': ')[1])) * coefficient
            elif line.startswith('Outgroup:'):
                outgroup = line.split(': ')[1].strip()

        report.append(f'Reticulations: {reticulations}')
        report.append(f'Taxa: {taxa}')
        report.append(f'Increase: {increase}')
        report.append(f'Decrease: {decrease}')
        report.append(f'Outgroup: {outgroup}')

    with open(output_file, 'w') as f:
        f.write('\n'.join(report)))

