import time

def terminate_process(pid, initial_sleep=1, max_sleep=30, factor=2):
    if not os.path.exists(f'/proc/{pid}'):
        return -1

    attempts = 0
    sleep_time = initial_sleep

    while attempts < max_sleep:
        try:
            os.kill(pid, signal.SIGTERM))
            return 0
        except ProcessLookupError:
            return -1
        except PermissionError:
            return -1

        time.sleep(sleep_time)
        sleep_time *= factor
        attempts += 1

    return -1

