        filter_func = pickle.loads(shelf['filter_func']))
    return filter_func

import warnings

def deprecate_attribute(old_name, new_name, version):
    def decorator(cls):
        old_attr = getattr(cls, old_name, None)

        if old_attr is not None:
            warnings.warn(f"Attribute '{old_name}' is deprecated and will be removed in version {version}. Use '{new_name}' instead.", DeprecationWarning, stacklevel=2)

            @property
            def _new_attr(self):
                return getattr(self, new_name, None)

            @property
            def _old_attr(self):
                return old_attr

            def _set_new_attr(self, value):
                setattr(self, new_name, value)

            def _set_old_attr(self, value):
                warnings.warn(f"Attribute '{old_name}' is deprecated and will be removed in version {version}. Use '{new_name}' instead.", DeprecationWarning, stacklevel=2)
                setattr(self, old_name, value)

            setattr(cls, old_name, property(_old_attr, _set_old_attr)))
            setattr(cls, new_name, property(_new_attr, _set_new_attr)))

        return cls

    return decorator

