import os
from django.core.mail import send_mail

def send_email(subject, message, from_email, recipient_list):
    if len(recipient_list) == 0:
        raise ValueError("Recipient list cannot be empty")

    if len(recipient_list) > 1:
        raise ValueError("Cannot send email to multiple recipients")

    recipient = recipient_list[0]

    if os.environ.get('DJANGO_SETTINGS_MODULE'):
        send_mail(subject, message, from_email, [recipient])
    else:
        os.system(f"echo '{message}' | mail -s '{subject}' {recipient}")

    if os.environ.get('VERBOSE') and int(os.environ.get('VERBOSE'))) >= 2:
        print(f"Sending email to {recipient} with subject '{subject}' from {from_email}")

