import json

def deserialize_object(json_str, decode_keys=False):
    def decode_key(key):
        try:
            return json.loads(key)
        except (json.JSONDecodeError, ValueError):
            return key

    def decode_value(value):
        try:
            return json.loads(value)
        except (json.JSONDecodeError, ValueError):
            return value

    def decode_dict(dct):
        if decode_keys:
            return {decode_key(k): decode_value(v) for k, v in dct.items()}
        return {decode_key(k): decode_value(v) for k, v in dct.items()}

    return json.loads(json_str, object_hook=decode_dict))

