def handle_python_version(module_name, version_specific_imports):
    try:
        if sys.version_info < version_specific_imports['min_version']:
            raise ImportError(f"Module '{module_name}' requires Python version {version_specific_imports['min_version']} or higher.")
        return __import__(module_name)
    except ImportError as e:
        tb = traceback.format_exc()
        raise ImportError(f"Failed to import module '{module_name}': {e}\nTraceback:\n{tb}") from e

