from pathlib import Path

def create_staging_folders(products, build_folder):
    for product, packages in products.items():
        staging_folder = os.path.join(build_folder, f'{product}_staging'))
        os.makedirs(staging_folder, exist_ok=True)
        for package in packages:
            download_and_extract(package, staging_folder)

def download_and_extract(url, extract_to):
    response = requests.get(url)
    response.raise_for_status()
    with zipfile.ZipFile(io.BytesIO(response.content))) as zip_ref:
        zip_ref.extractall(extract_to)

def move_to_final_folder(staging_folder, final_folder):
    for item in os.listdir(staging_folder):
        item_path = os.path.join(staging_folder, item))
        final_item_path = os.path.join(final_folder, item))
        if os.path.isdir(item_path):
            shutil.copytree(item_path, final_item_path, dirs_exist_ok=True)
        else:
            shutil.copy2(item_path, final_item_path)

def create_zip_file(final_folder, zip_filename):
    with zipfile.ZipFile(zip_filename, 'w', zipfile.ZIP_DEFLATED) as zipf:
        for root, dirs, files in os.walk(final_folder):
            for file in files:
                file_path = os.path.join(root, file))
                arcname = os.path.relpath(file_path, start=final_folder))
                zipf.write(file_path, arcname)

