    public static void main(String[] args) {
        if (args.length < 4) {
            System.out.println("Usage: java ANTLRRunner <directory> <file> <options>");
            return;
        }

        String directory = args[0];
        String file = args[1];
        String options = args[2];

        File inputFile = new File(directory, file);
        if (!inputFile.exists()) {
            System.out.println("File not found: " + inputFile.getAbsolutePath());
            return;
        }

        List<String> command = new ArrayList<>();
        command.add("java");
        command.add("-jar");
        command.add("antlr-4.13.0-complete.jar");
        command.add("-Dlanguage=Java");
        command.add("-o");
        command.add(directory);
        command.add(inputFile.getName());
        command.addAll(List.of(options.split(" "))))));

        ProcessBuilder processBuilder = new ProcessBuilder(command);
        processBuilder.redirectErrorStream(true);

        try {
            Process process = processBuilder.start();
            BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream())));
            String line;
            while ((line = reader.readLine()) != null) {
                System.out.println(line);
            }
            int exitCode = process.waitFor();
            System.out.println("ANTLR process exited with code " + exitCode);
        } catch (IOException | InterruptedException e) {
            e.printStackTrace();
        }
    }
}

