struct IoFactory;

impl IoFactory {
    fn create_task<F>(f: F) -> Task
    where
        F: FnOnce() -> Result + Send + 'static,
    {
        Task::new(f)
    }
}

struct Task {
    future: Pin<Box<dyn Future<Output = Result>> + Send>>,
}

impl Task {
    fn new<F>(f: F) -> Self
    where
        F: FnOnce() -> Result + Send + 'static,
    {
        Self {
            future: Box::pin(async move { f() })),
        }
    }
}

fn execute<F>(f: F) -> Result
where
    F: FnOnce() -> Result + Send + 'static,
{
    let task = IoFactory::create_task(f);
    let mut cx = Context::from_waker(futures_util::task::noop_waker_ref()));
    match task.future.poll(&mut cx) {
        Poll::Ready(Ok(_))) => Ok(()),
        Poll::Ready(Err(e))) => Err(e),
        Poll::Pending => Err(io::Error::new(io::ErrorKind::Other, "Task is still pending"))),
    }
}

