} AudioDevice;

AudioDevice* open_audio_device(const char* device_name, int frequency, int channels, int samples, void (*callback)(void*, Uint8*, int), void* userdata) {
    AudioDevice* device = (AudioDevice*)malloc(sizeof(AudioDevice)));
    if (!device) {
        fprintf(stderr, "Failed to allocate memory for audio device\n");
        return NULL;
    }
    device->desired.freq = frequency;
    device->desired.format = AUDIO_S16SYS;
    device->desired.channels = channels;
    device->desired.samples = samples;
    device->desired.callback = callback;
    device->desired.userdata = userdata;
    device->device_id = SDL_OpenAudioDevice(device_name, 0, &device->desired, &device->obtained), 1);
    if (device->device_id == 0) {
        fprintf(stderr, "Failed to open audio device: %s\n", SDL_GetError());
        free(device);
        return NULL;
    }
    return device;
}

