use cargo::core::package::PackageId;
use cargo::core::resolver::Resolve;
use cargo::core::source::Source;
use cargo::ops::cargo_add::add;
use cargo::ops::cargo_update::update;
use std::path::Path;

fn update_cargo_toml(
    dir: &Path,
    verbose: bool,
    quiet: bool,
    color: bool,
    frozen: bool,
    locked: bool,
    manifest_path: Option<&Path>>,
) -> Result<(), Box<dyn std::error::Error>>> {
    let manifest = Manifest::from_path(dir.join("Cargo.toml")))?;
    let mut resolve = Resolve::new(&manifest)?;
    let mut source = Source::new(&manifest, &mut resolve, &mut source)?)?;
    let mut package_id = PackageId::new(&manifest.name, &manifest.version))?;
    let mut add_options = cargo_add::AddOptions::new();
    add_options.verbose = verbose;
    add_options.quiet = quiet;
    add_options.color = color;
    add_options.frozen = frozen;
    add_options.locked = locked;
    add_options.manifest_path = manifest_path.map(|p| p.to_path_buf()));
    add(&mut source, &mut package_id, &add_options)?;
    update(&mut source, &mut package_id, &add_options)?;
    Ok(())
}

