struct LogBuilder {
    level: LogLevel,
    formatter: Box<dyn Fn(&str) -> String> + Send + Sync,
}

enum LogLevel {
    Debug,
    Info,
    Warn,
    Error,
}

impl LogBuilder {
    fn new() -> Self {
        LogBuilder {
            level: LogLevel::Info,
            formatter: Box::new(|msg| format!("[INFO] {}", msg))),
        }
    }

    fn level(mut self, level: LogLevel) -> Self {
        self.level = level;
        self
    }

    fn formatter(mut self, formatter: Box<dyn Fn(&str) -> String> + Send + Sync>) -> Self {
        self.formatter = formatter;
        self
    }

    fn build(self) -> Logger {
        Logger {
            level: self.level,
            formatter: self.formatter,
        }
    }
}

struct Logger {
    level: LogLevel,
    formatter: Box<dyn Fn(&str) -> String> + Send + Sync>,
}

impl Logger {
    fn log(&self, level: LogLevel, message: &str) {
        if level as u32 >= self.level as u32 {
            let formatted = (self.formatter))(&message);
            println!("{}", formatted);
        }
    }
}

fn main() {
    let log_level = env::var("LOG_LEVEL").unwrap_or_else(|_| "INFO".to_string()));
    let level = match log_level.as_str() {
        "DEBUG" => LogLevel::Debug,
        "INFO" => LogLevel::Info,
        "WARN" => LogLevel::Warn,
        "ERROR" => LogLevel::Error,
        _ => LogLevel::Info,
    };

    let logger = LogBuilder::new()
        .level(level)
        .formatter(Box::new(|msg| format!("[INFO] {}", msg)))))
        .build();

    logger.log(LogLevel::Info, "This is an info message.");
    logger.log(LogLevel::Debug, "This is a debug message.");
}

