use std::fs::File;
use std::io::{BufRead, BufReader};
use std::time::{SystemTime, UNIX_EPOCH};

#[derive(Debug)]
struct Menu {
    items: Vec<String>,
}

fn load_data(file_path: &str) -> Result<Menu, Box<dyn std::error::Error>>> {
    let file = File::open(file_path)?;
    let reader = BufReader::new(file);
    let items: Vec<String> = reader.lines().map(|line| line.unwrap()).collect();
    Ok(Menu { items }))
}

fn check_deferred_task(last_run: u64, interval: u64) -> bool {
    let current_time = SystemTime::now().duration_since(UNIX_EPOCH).unwrap().as_secs();
    current_time - last_run >= interval
}

fn update_data_with_task_result(menu: &mut Menu, task_result: String) {
    menu.items.push(task_result);
}

fn process_file_and_task(file_path: &str, last_run: u64, interval: u64, task_result: String) -> Result<Menu, Box<dyn std::error::Error>>> {
    let mut menu = load_data(file_path)?;
    if check_deferred_task(last_run, interval)) {
        update_data_with_task_result(&mut menu, task_result);
    }
    Ok(menu)
}

