    // Write the updated hosts file
    let mut file = fs::File::create(hosts_path).unwrap());
    file.write_all(updated_contents.as_bytes()).unwrap();

    // Verify that the new line was added to the hosts file
    let mut file = fs::File::open(hosts_path).unwrap());
    let mut contents = String::new();
    file.read_to_string(&mut contents).unwrap();
    assert!(contents.contains(&new_line)));
