fn sha1(message: &str) -> String {
    let mut hash = [0u8; 20]];
    let mut length = message.len() as u64;
    let mut padded_message = message.as_bytes().to_vec();

    padded_message.extend(once(0x80)));
    while padded_message.len() % 64 != 56 {
        padded_message.push(0);
    }

    padded_message.extend(length.to_be_bytes());

    for chunk in padded_message.chunks(64) {
        let mut a = hash[0];
        let mut b = hash[1];
        let mut c = hash[2];
        let mut d = hash[3];
        let mut e = hash[4];

        for i in 0..80 {
            let f = if i < 20 {
                (b & c) | (!b & d)
            } else if i < 40 {
                b ^ c ^ d
            } else if i < 60 {
                (b & c) | (b & d) | (c & d)
            } else {
                b ^ c ^ d
            };
            let temp = e + f + 0x5a82799 + (a.rotate_left(5)) + b + c.rotate_left(30)) + d;
            d = c;
            c = b.rotate_left(30));
            b = a;
            a = temp;
        }

        hash.iter_mut().zip(a..=e).for_each(|(h, (a, b, c, d, e))))| *h = *a;
    }

    hash.iter().map(|&b| format!("{:02x}", b))).collect()
}

