use std::fs;
use std::path::Path;

fn copy_files_except(source: &Path, destination: &Path) -> std::io::Result<()> {
    if !source.exists() {
        return Err(std::io::Error::new(std::io::ErrorKind::NotFound, "Source path does not exist"))));
    }

    if !destination.exists() {
        fs::create_dir_all(destination)?;
    }

    for entry in fs::read_dir(source)? {
        let entry = entry?;
        let path = entry.path();
        let file_name = path.file_name().unwrap().to_str().unwrap();

        if !destination.join(file_name).exists() {
            if path.is_dir() {
                fs::create_dir_all(destination.join(file_name)))?;
                copy_files_except(&path, &destination.join(file_name)))?;
            } else {
                fs::copy(&path, destination.join(file_name)))?;
            }
        }
    }

    Ok(())
}

