use sqlx::postgres::PgPoolOptions;
use std::env;

async fn setup_db_connection(db_url: &str) -> Result<PgPoolOptions> {
    let pool = PgPoolOptions::new()
        .max_connections(5)
        .connect(db_url)
        .await?;
    Ok(pool)
}

async fn commit_transaction(req: &HttpRequest) -> Result<()> {
    if let Some(tx) = req.extensions().get::<sqlx::Transaction<'_>>>() {
        tx.commit().await?;
    }
    Ok(())
}

async fn middleware(req: HttpRequest, next: actix_web::dev::Next) -> Result<HttpResponse> {
    let db_url = env::var("DATABASE_URL").expect("DATABASE_URL must be set");
    let pool = setup_db_connection(&db_url).await?;
    let tx = pool.begin().await?;
    req.extensions_mut().insert(tx);
    let response = next.run(req).await?;
    commit_transaction(&req).await?;
    Ok(response)
}

