#[derive(Debug)]
struct Options {
    help: bool,
    commits: u32,
}

impl Options {
    fn new(args: &[String]) -> Self {
        let mut help = false;
        let mut commits = 0;

        for arg in args.iter().skip(1) {
            match arg.as_str() {
                "--help" => help = true,
                "--commits" => {
                    if let Some(val) = args.iter().skip(2).next() {
                        if let Ok(num) = val.parse::<u32>() {
                            commits = num;
                        }
                    }
                }
                _ => {}
            }
        }

        Self { help, commits }
    }
}

fn display_help() -> String {
    format!(
        "Usage: git-commit --commits <number> [--help]\n\n\
        Options:\n\
        --commits <number>  Specify the number of commits to create.\n\
        --help                        Display this help message and exit.\n\n\
        Description:\n\
        This command creates a specified number of commits in a Git repository. Each commit will have a unique message and timestamp. The --help option provides detailed usage information and a list of available options."
    )
}

fn main() {
    let args: Vec<String> = std::env::args().collect();
    let options = Options::new(&args);

    if options.help {
        println!("{}", display_help());
        std::process::exit(0);
    }

    println!("Creating {} commits...", options.commits);
    // Simulate commit creation
    for i in 0..options.commits {
        println!("Commit {} created.", i + 1);
    }
}

