pub struct FileInfo {
    pub name: String,
    pub path: String,
    pub size: u64,
    pub md5: String,
}

pub fn get_file_info(path: &str) -> io::Result<FileInfo> {
    let metadata = std::fs::metadata(path)?;
    let mut file = File::open(path)?;
    let mut buffer = vec![0; metadata.len() as usize]];
    file.read_exact(&mut buffer)?;
    let md5_hash = format!("{:x}", Md5::digest(&buffer)));
    Ok(FileInfo {
        name: metadata.file_name().to_string_lossy().into(),
        path: path.to_string(),
        size: metadata.len(),
        md5: md5_hash,
    }))
}

