use std::process::Command;
use std::sync::atomic::{AtomicU64, Ordering};
use std::sync::Once;
use std::error::Error;
use std::fmt;

static mut START_RSS: u64 = 0;
static mut END_RSS: u64 = 0;
static START_RSS_INIT: Once = Once::new();

fn get_resident_set_size() -> u64 {
    unsafe {
        START_RSS_INIT.call_once(|| {
            START_RSS = libc::getrusage(libc::RUSAGE_SELF, std::ptr::null_mut()) as u64;
        });
        END_RSS = libc::getrusage(libc::RUSAGE_SELF, std::ptr::null_mut()) as u64;
        END_RSS - START_RSS
    }
}

fn compile_rust_with_logging() -> Result<(), Box<dyn Error>>> {
    let start_time = Instant::now();
    let start_rss = get_resident_set_size();
    let output = Command::new("rustc")
        .arg("--crate-type=bin")
        .arg("--crate-name=my_crate")
        .arg("--out-dir=./target/debug")
        .arg("./src/main.rs")
        .output()?;
    let end_rss = get_resident_set_size();
    let elapsed_time = start_time.elapsed();
    println!("Compilation completed in {}.{:03} seconds", elapsed_time.as_secs(), elapsed_time.subsec_millis());
    println!("Memory usage: {} KB", (end_rss - start_rss) / 1024);
    if !output.status.success() {
        eprintln!("Compilation failed with status: {}", output.status);
        eprintln!("Stdout: {}", String::from_utf8_lossy(&output.stdout)));
        eprintln!("Stderr: {}", String::from_utf8_lossy(&output.stderr)));
        return Err("Compilation failed".into());
    }
    Ok(())
}

