async fn read_config_files() -> (IrcConfig, BotConfig) {
    let config_files = HashMap::from([
        ("irc_config.toml", IrcConfig::deserialize)),
        ("bot_config.toml", BotConfig::deserialize)),
    ]);

    let mut futures = Vec::new();

    for (file_path, deserialize_fn) in config_files {
        let file = File::open(file_path).await.unwrap();
        let reader = BufReader::new(file);
        let future = async move {
            let config: T = deserialize_fn(reader).await.unwrap();
            config
        };
        futures.push(future);
    }

    let (irc_config, bot_config) = join_all(futures).await;
    (irc_config, bot_config)
}

