fn fold_header_value(input: &str, max_line_length: usize) -> String {
    let mut folded_value = String::new();
    let mut current_line_length = 0;

    for part in input.split(',') {
        let part = part.trim();
        let part_length = part.len();

        if current_line_length + part_length + 1 > max_line_length {
            folded_value.push('\n');
            current_line_length = 0;
