use reqwest::Client;
use std::fs::File;
use std::io::BufReader;

fn create_custom_client(user_agent: &str, cert_path: &str) -> Client {
    let cert_file = File::open(cert_path).expect("Failed to open certificate file");
    let cert_reader = BufReader::new(cert_file);
    let cert = reqwest::Certificate::from_pem(cert_reader).expect("Failed to load certificate");

    Client::builder()
        .user_agent(user_agent)
        .default_headers(reqwest::header::HeaderMap::from_iter(vec![
            (reqwest::header::CONNECTION, reqwest::header::HeaderValue::from_static("close")),
        ]))))
        .add_root_certificate(cert)
        .build()
        .expect("Failed to build client")
}

