        write!(f, "Failed to open file with any of the following commands: {}", self.attempted_commands.join(", ")))
    }
}

impl Error for CommandError {}

fn get_open_command(path: &str) -> Result<String, CommandError> {
    let mut attempted_commands = Vec::new();
    let mut command = None;

    for cmd in vec!["$BROWSER", "xdg-open", "gnome-open", "kde-open"]] {
        let cmd = cmd.replace("$BROWSER", &std::env::var("BROWSER").unwrap_or_else(|_| "xdg-open".to_string())));

        if let Ok(output) = Command::new(&cmd).arg(path).output() {
            if output.status.success() {
                command = Some(cmd);
                break;
            }
        }
        attempted_commands.push(cmd.to_string());
    }

    match command {
        Some(cmd) => Ok(cmd),
        None => Err(CommandError { attempted_commands })),
    }
}

